/* 第 39 章 — 1:1 演出流，逆向自 R_39.eex */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch39","num":39,"title":"第 39 章","desc":"第 39 章（原版剧本 R_39.eex 完整演出流）","intro":{"title":"第 39 章","script":[{"op":"clear_flags","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,14,65535]},{"op":"actor_appear","args":[0,52,61,0,0]},{"op":"actor_appear","args":[2,52,65,0,0]},{"op":"actor_appear","args":[218,52,45,2,0]},{"op":"actor_appear","args":[648,52,40,2,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["和谈"]},{"op":"place_name","args":["凉州战场"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n鲜卑王你应该很明白，这场仗再打下去，\n对双方都没有任何好处。"]},{"op":"dialog","args":["&秃发机能\n本王同意，到时只怕魏国趁虚而入，\n凉州又会落入他们的手中。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n那么就这样吧，我们汉人退出河西之地，\n而鲜卑人则退出陇西郡以西，中间的势力\n画分再由双方商议。\n&姜维\n之后双方继续保持合作，我会请求朝廷\n制定维持双方贸易和生存空间的法律。"]},{"op":"actor_action","args":[218,5]},{"op":"dialog","args":["&秃发机能\n好，干脆痛快，汉人像你这样的可不多\n呀。"]},{"op":"actor_action","args":[218,0]},{"op":"dialog","args":["&姜维\n在下是天水人，对于外族的需求也不是\n没有体会，在下不会做出和过去那些人\n相同的镇压行为。"]},{"op":"actor_action","args":[2,6]},{"op":"dialog","args":["&杨兰\n我也是羌人，之所以愿意和大汉将士\n一起作战，就是因为大汉和魏国不同。"]},{"op":"actor_action","args":[218,6]},{"op":"dialog","args":["&秃发机能\n本王明白了，你们就放心东进吧。\n我也很期待你们灭掉魏国。"]},{"op":"dialog","args":["&若罗拔能\n（大王，我们好不容易才打败汉人，难道\n就这样放过凉州？）"]},{"op":"dialog","args":["&秃发机能\n（这些汉人还是很蠢，以为我们是过去\n那些只满足于金钱、物资的蛮族。）"]},{"op":"dialog","args":["&秃发机能\n（现在他们兵势不弱，和他们交战确实\n没有好处，不如卖个面子，等以后他们\n兵锋向东再来攻打。）"]},{"op":"dialog","args":["&若罗拔能\n（大王，好个兵不厌诈。）"]},{"op":"dialog","args":["&秃发机能\n（这叫做战争头脑，谁说我们鲜卑人\n不会用脑？我可要成为超越轲比能的\n鲜卑王。）"]},{"op":"actor_action","args":[218,0]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,218,0,46,5,0]},{"op":"actor_move","args":[0,648,0,46,5,0]},{"op":"actor_select","args":[0,218,0,0,0,0,6]},{"op":"actor_select","args":[0,648,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[0,0,2]},{"op":"actor_action","args":[2,0]},{"op":"dialog","args":["&杨兰\n姜维，这个人讲话不可信。\n&杨兰\n我认为他和姚柯回差不了多少，胸怀野心\n，随时会反咬我们一口。\n&姜维\n现在我们没有多余的战力和他们交战，\n别忘记邓艾还在祁山那边虎视眈眈。\n&姜维\n我不求在这里有充份的统治，只要让曹贼\n的势力从这被排除就够了。\n&杨兰\n那么你的想法是…\n&姜维\n一方面想办法把靠近鲜卑的人民往东迁，\n避免和鲜卑或是羌人冲突。\n&姜维\n另一方面急速派兵东进，把祁山以东地方\n都纳入我军势力范围，但是不要浪费兵力\n在统治上。\n&姜维\n所有的统治都委托当地人，关西大族虽然\n过去受到过不少打压，但力量仍然不容忽\n视。\n&姜维\n这种委由当地大族间接统治的方式，\n其实就和丞相的南中治理政策有异曲\n同工之妙。\n&杨兰\n我想我可以结好羌人，过去王嗣建立的\n人脉，现在可以派上用场。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n那么一切就麻烦你了。\n&姜维\n（就和上次一样，现在挡著我回到冀城的\n，就只剩下邓艾而已。）\n&姜维\n（这次不会再输了，你等着吧，邓艾。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[14,51,54,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["马隆的决定"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"delay","args":[5]},{"op":"if","cond":"test_flags","args":[[],[310]],"end":13},{"op":"dialog","args":["&姜维\n你应该就是马孝兴吧。我是大汉大将军\n姜维。\n&姜维\n当我接到信的那刻，很高兴知道这世上\n还有如此人才。\n&姜维\n不知是否愿意弃暗投明，归顺我大汉呢？\n&马隆\n那么请回答一个问题，你明知蜀国国小\n民贫，却再三对我大魏发动攻势，所求\n到底为何？\n&姜维\n和当年的我一模一样呀。\n&姜维\n当年我也问丞相这样的问题，丞相回答\n说是知遇之恩。\n&姜维\n但我知道那样的回答或许可以满足我，\n却不一定可以满足你。\n&姜维\n我奋战是为了许多因素，既为了报恩，\n也为了实现承诺。\n&马隆\n结果到头来，你还是跟在刘备和诸葛亮\n后面，单纯执行著他们的遗志而已？\n&姜维\n何出此言？\n&马隆\n说实话，我并不讨厌这样浪漫的想法，\n只是这样的格局实在是太小了。\n&马隆\n要打倒有著庞大利益作为后盾的司马家，\n这种程度的情义并不够。\n&姜维\n你说的对…但你眼中这点小情小义，就\n足够支撑我辅汉近四十年。\n&马隆\n我很难认同你的想法，不过说我没有意愿\n加入你们是骗人的。\n&马隆\n在兖州被埋没十数载，最后被丢到边地，\n我不甘心自己就这样结束一生。\n&姜维\n那么，就用丞相当年说过的话来对你说。\n&姜维\n这里就是你的舞台，也是千载难逢的机会\n，我希望你能成为我的接班人。"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n这样诱人的条件我是不会拒绝的，\n东平马隆愿为大汉效力！"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[310],[]],"end":18},{"op":"dialog","args":["&马隆\n之前你请我考虑的结果，我已经决定了…"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n这样诱人的条件我是不会拒绝的，\n东平马隆愿为大汉效力！"]},{"op":"endif","args":[]},{"op":"actor_action","args":[14,0]},{"op":"dialog","args":["&姜维\n那么换我问你一个问题。\n&姜维\n你想要成为什么样的将领？"]},{"op":"choice","args":["智勇双全\n谋略过人\n武勇过人",14]},{"op":"if","cond":"always","args":[],"end":50},{"op":"if","cond":"test_choice","args":[1],"end":25},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我的志向就是像你一样，既能在后方指挥\n全军，又可以在前线和敌人拚搏。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":29},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我的志向就是像诸葛丞相那样，\n以谋略战胜敌人。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[3],"end":49},{"op":"choice","args":["轻骑兵\n白马骑（伪随机模式可选）\n宿卫骑（伪随机模式可选）",14]},{"op":"if","cond":"always","args":[],"end":48},{"op":"if","cond":"test_choice","args":[1],"end":35},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我的志向就是像张辽或是关羽将军那样，\n以一己的武勇为我军冲开一条路。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":41},{"op":"if","cond":"test_flags","args":[[1102],[]],"end":40},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我的志向就是像张辽或是关羽将军那样，\n以一己的武勇为我军冲开一条路。"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[3],"end":47},{"op":"if","cond":"test_flags","args":[[1102],[]],"end":46},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我的志向就是像张辽或是关羽将军那样，\n以一己的武勇为我军冲开一条路。"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"actor_action","args":[14,0]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[15,96,54,3,0]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,15,0,58,54,3]},{"op":"actor_action","args":[15,0]},{"op":"actor_face","args":[14,0,1]},{"op":"delay","args":[5]},{"op":"actor_action","args":[15,6]},{"op":"dialog","args":["&张翼\n伯约，当时我说过，在这场仗打完后有话\n要对你说。\n&张翼\n现在是时候了。\n&姜维\n伯恭请说吧。\n&张翼\n我们可以到外面去说吗？\n&姜维\n孝兴不是外人，没有关系的。\n&马隆\n不，我大概明白是怎么回事了。"]},{"op":"actor_face","args":[14,0,3]},{"op":"dialog","args":["&马隆\n大将军，您被期望很高喔。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,39,65535,68,65535]},{"op":"actor_appear","args":[0,48,61,1,0]},{"op":"actor_appear","args":[15,53,61,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["张翼的请求"]},{"op":"place_name","args":["凉州"]},{"op":"dialog","args":["&姜维\n伯恭，到底有什么话一定要在这里说？\n难道是什么不可告人之事？\n&张翼\n说不可告人也算对，这件事情关系重大\n，我不希望太多人被牵扯进来。\n&张翼\n伯约，你希不希望得到益州人的全面\n协助？\n&张翼\n你知道我们大汉的国力其实没有发挥到\n极致。最重要的原因，就是我们益州人\n不肯配合。\n&张翼\n北伐对我们来说，劳民伤财却又没有什么\n好处，所以我们才会反对到底。\n&张翼\n这样下去，就算伯约你成功攻略凉州，\n我们益州人也会阻止你继续东进。\n&姜维\n那么我该怎么做，才能得到你们益州人\n的支持？\n&张翼\n其实你只要给我们愿景就行。\n&张翼\n我们益州人不断被外来人士所统治，\n公孙述、刘焉父子、甚至是现在的皇家\n，每个人都给我们痛苦的回忆。\n&张翼\n我们很悲愤，却无力反抗，只能用消极\n不配合的态度表示抗议。\n&张翼\n但是如果说，这次北伐成功后，我们\n益州人可以得到解放，情况就大不相同。\n&姜维\n我明白了。就是当光复洛阳的同时，让\n所有外州人都迁出，还给你们益州人土地\n是吗？"]},{"op":"actor_action","args":[15,6]},{"op":"dialog","args":["&张翼\n正是如此。\n&张翼\n这个建议已经接近谋逆，我早就已经\n豁出去了，你要把我移送也毫无怨言。\n&姜维\n不，伯恭所言有理。只恨我过去眼界\n太低，心胸太窄，从来不肯站在益州人\n角度来看事情。\n&姜维\n我们大汉的首都自然就应该是洛阳，\n当光复洛阳时，岂有再霸占益州人土地\n的道理？\n&姜维\n我认为以陛下的圣明，他应该也会\n同意的。\n&张翼\n那么…"]},{"op":"actor_action","args":[15,0]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n我会即刻上书陛下，请他慎重考虑这样\n的建议。\n&姜维\n纵然这是越权行为，但是关系到大汉的\n光复大业，我想陛下也会慎重考虑的。"]},{"op":"actor_action","args":[15,4]},{"op":"dialog","args":["&张翼\n多谢…我代表益州数十万居民感谢你…\n&姜维\n（一向刚强的张伯恭也会有落下男儿泪的\n一天，自由果然是大家最想追求的。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[68,51,29,2,0]},{"op":"actor_appear","args":[24,58,34,0,0]},{"op":"actor_appear","args":[669,41,47,1,0]},{"op":"actor_appear","args":[665,41,52,1,0]},{"op":"actor_appear","args":[7,65,47,3,0]},{"op":"actor_appear","args":[713,65,52,3,0]},{"op":"actor_appear","args":[84,65,57,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["邺城宫殿"]},{"op":"title_text","args":["惊奇的复活"]},{"op":"dialog","args":["&曹绫\n陛下，要赢得这场战争，光靠我们的力量\n是不够的。\n&曹绫\n所以我提议，让我和夏侯将军两人前往\n凉州和蜀人同盟。\n&何曾\n回想起过去我们和蜀人斗了这么多年，\n没想到现在居然要和他们联手。\n&嵇凛\n时势的变化正是如此，过去支持司马家的\n，现在也可能倒向我们阵营，不是吗？\n&何曾\n你说得对…\n&何曾\n（唉…明知道这小姑娘在酸老夫，却也\n无言以对。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n只有让蜀人在西线获胜，而我们在北面\n获胜。两面包夹司隶，才有攻下的可能。\n&曹芳\n朕明白了，毕竟两国的恩怨是过去的事。\n现在我们有司马家这个共同的敌人，合作\n也是应该的。\n&曹芳\n只是同盟的工作，只需要派一个使者过去\n即可，何必要像姑姑这样重要的人去呢？\n&曹绫\n因为双方交战了数十年，彼此都心有芥蒂\n。如果不能表示我们的诚意，同盟恐怕很\n难达成。\n&曹绫\n我和蜀人大将军姜维有过一面之缘，而\n夏侯将军更是担任过蜀地的车骑将军。\n由我们去，更可以表现出诚意。\n&曹绫\n更何况，我希望和蜀人沟通的事情，\n可不是只有同盟这么容易而已。"]},{"op":"actor_face","args":[665,6,0]},{"op":"dialog","args":["&山涛\n公主的想法我是可以理解，不过现实上\n有个极大的问题。"]},{"op":"actor_face","args":[24,6,2]},{"op":"dialog","args":["&曹绫\n请说。"]},{"op":"actor_action","args":[24,0]},{"op":"dialog","args":["&山涛\n我们这边虽然有兵，但是擅长指挥作战的\n大将并不多。\n&山涛\n有指挥过大兵团作战的，更只有公主和\n夏侯将军两人而已。\n&山涛\n万一两位一同前去凉州，试问谁可以统率\n这些部队？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&何曾\n咳…各位是不是忘了一个人了…\n&嵇凛\n我想您是国家的元老重臣，还是歇歇吧。"]},{"op":"actor_action","args":[669,2]},{"op":"dialog","args":["&何曾\n喂！老夫好歹也是镇北将军吧！"]},{"op":"actor_action","args":[669,0]},{"op":"actor_face","args":[665,0,1]},{"op":"dialog","args":["&山涛\n凛儿，你上殿已经是严重破坏规矩了，\n不可在这样放肆。\n&曹芳\n朕倒是很喜欢这种抛开一切规矩的朝议。\n想当初，朕在司马师面前可是连口大气都\n不敢喘呢。\n&曹芳\n所以你想说什么，朕都让你说。"]},{"op":"actor_face","args":[84,6,0]},{"op":"dialog","args":["&嵇凛\n陛下圣明。"]},{"op":"actor_face","args":[669,0,0]},{"op":"dialog","args":["&何曾\n陛下，老臣说的不是自己，老臣也知道\n自己年老无用，除了鉴赏美食以外已经\n一无是处。\n&何曾\n只怪当时没把话说清楚，当时说服老夫\n投靠这边的，除了公主外，还另有其人。\n&山涛\n对呀！我们居然忘了他，不是听说他已经\n在前往邺城途中？\n&桓楷\n究竟是谁？"]},{"op":"actor_appear","args":[112,51,98,0,0]},{"op":"actor_appear","args":[86,48,97,0,0]},{"op":"actor_appear","args":[88,55,99,0,0]},{"op":"actor_move","args":[0,112,0,51,55,0]},{"op":"actor_move","args":[0,86,0,48,60,0]},{"op":"actor_move","args":[0,88,0,55,60,0]},{"op":"actor_action","args":[112,0]},{"op":"actor_action","args":[86,0]},{"op":"actor_action","args":[88,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[112,6]},{"op":"dialog","args":["&陈泰\n臣陈泰，参见陛下！\n&曹芳\n朕没眼花吧？！不是听说玄伯你早在\n四年前就病逝了？\n&陈泰\n那是因为司马昭不断苦苦相逼，臣为了\n避免儿孙受到迫害，所以才想出以诈死\n摆脱司马家的压力。\n&陈泰\n本来想隐身在陈家大宅，不再出门一步\n，就此度过余生的。\n&陈泰\n没想到公主却来告诉我司马昭战死的消息\n，这让臣心中的枷锁完全解开了。\n&陈泰\n臣的父亲是大魏的忠臣，臣也是大魏的\n忠臣。不管臣和司马家有多密切的关系\n，臣现在只愿意效忠陛下。\n&陈泰\n现在臣还带来两位猛将助阵，这两位也是\n大魏的纯臣。"]},{"op":"actor_action","args":[86,6]},{"op":"dialog","args":["&张虎\n臣父亲深受大魏大恩，现在正是报效\n之时。\n&曹芳\n张辽的儿子吗？朕虽然未能亲眼目睹\n张将军当年的英勇，但是合肥之战的\n事迹却也听过很多次。"]},{"op":"actor_action","args":[88,6]},{"op":"dialog","args":["&戴陵\n臣戴陵，虽然算不上什么猛将，但也希望\n为大魏尽一份心力。\n&戴陵\n（当我知道乐綝死亡的真相时，我哪还能\n坐得住，张虎应该也是一样的吧。）\n&山涛\n只要有玄伯在，确实我们的军队就有人\n带领了。\n&曹芳\n过去陈将军带兵抵御姜维入侵多年，也\n担任过一方都督，确实是合适人选。\n&曹芳\n如此，朕可以放心让姑姑您去了。\n&曹芳\n姑姑，蜀人或许会表现很强硬，朕可以\n退让到削去帝号，效法曾祖成为汉臣，\n只求同盟成立。"]},{"op":"actor_face","args":[665,0,0]},{"op":"dialog","args":["&山涛\n陛下！\n&曹芳\n如果没有人退让的话，双方永远没有合作\n的可能。\n&曹芳\n更别忘记我们的敌人是庞大的司马家势力\n，现在已经没有时间再争执这些事情了。"]},{"op":"actor_face","args":[24,0,0]},{"op":"dialog","args":["&曹绫\n好的，我会传达给蜀人知道。\n&陈泰\n（子上，我已经下定决心要和司马家开战\n。其实早在你杀害高贵乡公的那刻，我就\n不再对司马家有任何期望了。）\n&陈泰\n（但是念在我们往日友情，我一定会想\n办法保护你的儿子，让他们在战败后还能\n生存下去。）"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,11,65535]},{"op":"actor_appear","args":[96,49,71,0,0]},{"op":"actor_appear","args":[199,36,55,1,0]},{"op":"actor_appear","args":[100,36,50,1,0]},{"op":"actor_appear","args":[102,36,45,1,0]},{"op":"actor_appear","args":[581,63,55,3,0]},{"op":"actor_appear","args":[721,63,50,3,0]},{"op":"actor_appear","args":[107,63,45,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["终极行动"]},{"op":"place_name","args":["洛阳相国府"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[96,17]},{"op":"dialog","args":["&司马炎\n从现在起，孤就正式成为晋王。"]},{"op":"actor_action","args":[96,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[199,6,2]},{"op":"dialog","args":["&荀勖\n恭喜相国…不，晋王！"]},{"op":"actor_face","args":[107,6,2]},{"op":"dialog","args":["&钟会\n晋王，虽然被封为晋王可喜可贺，但是\n我们不应该就这样满足。\n&魏舒\n难道要马上就要接受禅让？才刚当到晋王\n就接受禅让，只怕惹人非议。\n&钟会\n我们的敌人可不是只有洛阳这里，因为\n这连串的继承风波，让我们无暇他顾，\n明明知道凉州失陷都无法处理。\n&司马炎\n嗯…孤也知道凉州刺史胡烈战死的消息\n，蜀人和鲜卑人勾结，席卷了凉州大半\n土地。\n&钟会\n凉州失陷算事小，至少邓艾他还能遏守住\n祁山，不让蜀人部队东进。\n&钟会\n但是河北的局势就不寻常了。\n&钟会\n不管是河北督或是邺城督都没有任何消息\n传来。\n&司马炎\n这不是很好吗？\n&钟会\n但是明明就发生了一件大事…齐王曹芳\n失踪…\n&贾充\n什么？！难道他逃出监控？\n&钟会\n我认为应该是被反乱份子救出来了。\n而河北督和邺城督可能也倒向敌人那边。\n&司马炎\n这就怪了，何曾是文王所仰重的对象，\n他要出发担任河北督时，还要孤亲自送行\n数百里。\n&司马炎\n而邺城督山涛更是司马家的亲族，他没有\n反叛的道理。\n&钟会\n（笑死人了，你祖父司马懿受到明皇帝\n提拔成为托孤重臣，到最后还不是背叛\n明皇帝的期待？）\n&钟会\n不，何曾曾经是明皇帝的旧属，而山涛则\n是害怕嵇康的下场落到自己身上，他们都\n有反叛的动机。\n&魏舒\n（嵇康之死还不是钟会你弄出来的。）\n&司马炎\n真是意想不到…\n&钟会\n现在北面和西面都有乱事，我们如果不能\n集中力量平乱，只怕天下会为之颠覆。\n&荀顗\n只是…这和禅让有什么关系？\n&钟会\n曹芳的失踪定和邺城的东乡公主脱离不了\n关系。而圣上也是曹氏亲族…\n&贾充\n我懂了，用这件事来逼迫陛下，使他知道\n自己该怎么做。\n&钟会\n是呀，让曹奂知道自己是被牺牲的棋子，\n而他唯一可以依赖的对象只有我们。\n&司马炎\n一切都随你们高兴，孤什么都不知情，\n知道了吗？"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[30]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[133,29,54,1,0]},{"op":"actor_appear","args":[113,48,41,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["天命所在"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"actor_face","args":[113,0,3]},{"op":"dialog","args":["&陈骞\n前一阵子你奔回洛阳痛哭，居然还说那种\n恶心的话，真令人敬佩。\n&石苞\n嘿嘿，那可是我想了三天三夜才想出来的\n好点子。\n&石苞\n“您有这样的基业，居然还以人臣的身份\n死去？！”哈哈哈…"]},{"op":"actor_action","args":[113,2]},{"op":"dialog","args":["&陈骞\n你真是马屁精。"]},{"op":"actor_action","args":[113,0]},{"op":"dialog","args":["&石苞\n少来了，你以为我不知道你在想什么？\n还不是在怨恨自己拍马屁的脚步不快。\n&石苞\n你要知道，我特地把你从荆州叫过来，\n就是有好处跟你分享。\n&陈骞\n好处？\n&石苞\n我听说洛阳那边已经有劝进之声，要是\n慢了，只怕改朝换代后的位子都被抢光。\n&陈骞\n嗯…\n&石苞\n你还装什么忠臣？你本来是个绿豆小官，\n若不是文王提拔，你会有今天？\n&石苞\n而像我这寒门出身，也是仰赖景王提拔，\n才会有今日的地位，我们可没有任何忠于\n大魏的理由。\n&陈骞\n我同意，但是我不想和你联名上书。\n&石苞\n去你的，你以为我不知道你在荆州有多\n“招忌”？\n&石苞\n我们两人早就被洛阳那边合称“淫贱\n二老”，想不想和我凑在一起，根本\n由不得你。\n&陈骞\n好吧，那么劝进上书由你定？\n&石苞\n就说“历数已终，天命有在。”至于什么\n祥瑞的，你就弄个什么黄气数十丈。\n&石苞\n再不然，麒麟降生，凤凰来仪，黄龙出现\n，嘉禾蔚生，甘露下降，随便挑一个说说\n好了。\n&陈骞\n这些太老旧了。我早就已经想好了一个更\n新颖的祥瑞。\n&陈骞\n寿春城内，忽然天降一人，身长二丈余，\n脚长三尺二寸，白发苍苍，身著黄单衣；\n裹黄巾，挂藜头杖。\n&陈骞\n自称说：我是人民之王，现在特来告诉\n你，天下换主，立见太平。\n&石苞\n你真是唬烂的天才！还说自己无心劝进，\n你根本就比我还积极嘛。\n&石苞\n我看到时候，光靠著这样的功绩，你至少\n可以当到个骠骑将军。\n&陈骞\n可以不要“骠骑”吗？"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[30]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,17,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["石苞和陈骞两位都督联合上书表示大魏气数已尽，当改朝换代，顺应天命人心。",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["而由于此两人的推动，洛阳城内，劝进之声也是风起云涌，",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["彷彿司马炎不接受禅让是对不起天下苍生。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[70,51,29,2,0]},{"op":"actor_appear","args":[230,41,47,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"title_text","args":["皇帝悲歌"]},{"op":"dialog","args":["&曹奂\n黄门侍郎，朕终于明白朕的老爹（曹宇）\n当年为什么要拒绝托孤大臣的地位。\n&曹奂\n政治实在是太可怕了，一个不小心就会\n弄到满门抄斩。\n&张节\n陛下，您是皇帝，和曹爽、夏侯玄等人\n不一样呀。\n&曹奂\n就算是皇帝，高贵乡公的例子却还是历历\n在目，你以为朕完全安全？\n&曹奂\n朕只想早点解脱，把该做的事情做完。\n效法齐王，保全性命就不错了。\n&曹奂\n但是朕还是会怕呀，怕司马家的人还嫌慢\n，直接带著卫兵冲到朕的殿上。\n&曹奂\n朕已经不知道有多少个晚上梦见自己被杀\n，尸首被丢在洛水之滨无人收殓…"]},{"op":"actor_action","args":[230,0]},{"op":"dialog","args":["&张节\n陛下，绝对不会有这样的事情！微臣愿以\n自己的性命保护陛下！\n&曹奂\n呵呵呵呵呵…现在洛阳城中，可以称为\n大魏忠臣的，居然只剩你一个人而已。\n&曹奂\n朕已经可以体会当年汉献帝的苦情了，\n只是没想到武皇帝、文皇帝当年恶行的\n报应会来得如此之快。"]},{"op":"delay","args":[5]},{"op":"play_sound","args":[50]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[107,54,98,0,0]},{"op":"actor_appear","args":[100,54,98,0,0]},{"op":"actor_appear","args":[199,54,98,0,0]},{"op":"actor_appear","args":[226,54,98,0,0]},{"op":"actor_move","args":[0,107,0,39,52,0]},{"op":"actor_move","args":[0,226,0,39,62,0]},{"op":"actor_move","args":[0,199,0,64,52,0]},{"op":"actor_move","args":[0,100,0,64,62,0]},{"op":"actor_action","args":[107,0]},{"op":"actor_action","args":[226,0]},{"op":"actor_action","args":[199,0]},{"op":"actor_action","args":[100,0]},{"op":"actor_move","args":[0,230,0,51,48,2]},{"op":"actor_action","args":[230,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[199,6]},{"op":"dialog","args":["&荀勖\n臣等向陛下请安。\n&曹奂\n不知道众卿家有什么事情要来找朕？\n&钟会\n晋王听闻齐王曹芳日前从河内消失，料想\n是叛乱份子将他劫走，不知陛下是否知情\n呢？"]},{"op":"actor_move","args":[0,230,0,51,48,2]},{"op":"actor_action","args":[230,2]},{"op":"dialog","args":["&张节\n钟会！你这是责问陛下吗？这岂是人臣\n该有的作为？\n&曹奂\n无妨。朕对于这件事情一点也不知情。"]},{"op":"actor_action","args":[230,0]},{"op":"dialog","args":["&贾充\n那么陛下就可怜了…叛乱份子欲让曹芳\n复位，打从一开始就要舍弃陛下。\n&曹奂\n这也不意外，朕只是曹家的小宗，比起\n齐王是明皇帝亲自指定的继承人，朕实\n在是微不足道。\n&贾充\n陛下，叛乱就是叛乱！不管大宗小宗，\n叛乱份子立的皇帝就是伪帝，您这样说话\n，难道是要将天下拱手让出？\n&曹奂\n要说什么就直接说吧。\n&荀勖\n晋王想要守护天下，无奈天下臣民的\n早有归属，不再对大魏有向心力了。"]},{"op":"actor_action","args":[226,6]},{"op":"dialog","args":["&冯紞\n此时晋王如果以大魏之臣领导，恐怕得不\n到任何人响应。"]},{"op":"actor_action","args":[107,6]},{"op":"dialog","args":["&钟会\n为今之计，只有让天命所归的晋王暂时\n继承大统，延续大魏之国祚。等到乱平\n之日，再将皇位奉还。\n&曹奂\n搞了半天，不就是想要朕的皇位吗？\n&荀勖\n敢问皇上，大魏有今天，是谁出力最多？\n&曹奂\n大魏能有今日，当然是晋王的父…父亲、\n伯父与祖父所赐。\n&冯紞\n既然这样，陛下文不能论道，武不能经邦\n。何不把帝位让给有才德的明主呢？"]},{"op":"actor_action","args":[230,2]},{"op":"dialog","args":["&张节\n昔日高贵乡公有言：“司马昭之心，路人\n皆知。”今日倒是亲眼见闻。\n&张节\n美其名暂借天下，等到乱平之日就会\n奉还？真是见鬼的谎话！\n&张节\n说什么天下人心已经离开大魏，如果真是\n这样，为何还有人愿意拥立齐王？这岂是\n单单叛乱可以解释。\n&张节\n反观司马家倒行逆施，擅自废立；弑杀君\n王；残害忠臣；以礼教之名迫害名士，弄\n得天下人敢怒不敢言，何来人心归向？\n&贾充\n你个小小的黄门侍郎敢出口污蔑忠臣？\n&荀勖\n（太冲动了吧，居然连羚羊拳都使出来，\n难道接下来要用轮摆式位移？）\n&张节\n我说的哪里不对！昔日我魏武皇帝经过\n无数次的南征北讨，得此天下也不是件\n容易的事。\n&张节\n今日天子有德无罪，为什么要让给人呢？\n&钟会\n此社稷是大汉的社稷！曹操挟天子以令\n诸侯，自立魏王，篡夺汉室。\n&钟会\n司马家三世辅魏，今日之所以能得天下，\n绝非非曹氏之能，实在是司马氏之力。\n现在难道没资格去继承大魏的天下？\n&贾充\n（真敢说，这钟会真是不要脸到家了。）\n&冯紞\n（连大汉都抬出来，干脆直接说帮大汉\n报仇好了。）\n&张节\n晋王做这样的事情，就是篡国之贼！\n&荀勖\n晋王帮汉室复仇，有何不可。我曾祖\n（荀爽）乃大汉司空，对大汉忠心耿耿。\n我都支持晋王复仇，你还有什么话说？\n&冯紞\n（真是一山还有一山高，这荀勖不要脸到\n这种地步，真是佩服万分。）\n&荀勖\n（拜托曾祖晚上不要回来找我，我是\n被逼的。）\n&曹奂\n够了，不要说了。你们要什么，朕全都\n答应，只求你们放过黄门侍郎。"]},{"op":"actor_face","args":[230,0,0]},{"op":"dialog","args":["&张节\n陛下，微臣虽然赶不上夏侯玄、毌丘俭和\n诸葛诞，但能成为大魏最后的烈士，也是\n很荣幸的。\n&钟会\n庞会！动手！"]},{"op":"actor_appear","args":[57,48,97,0,0]},{"op":"actor_move","args":[0,57,0,48,48,1]},{"op":"actor_action","args":[57,0]},{"op":"actor_face","args":[230,0,2]},{"op":"dialog","args":["&张节\n我还想是谁，原来是庞德的儿子，这天下\n真是疯狂了。\n&张节\n当年忠臣的后代一个个变成走狗，荀爽、\n贾逵、钟繇、现在又多个庞德的儿子。\n&庞会\n……我眼里只有复仇，天下是谁的都和我\n无关。"]},{"op":"actor_action","args":[230,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[57,0,2]},{"op":"delay","args":[10]},{"op":"actor_move","args":[0,230,0,53,99,2]},{"op":"actor_move","args":[0,57,0,53,99,2]},{"op":"actor_select","args":[0,230,0,0,0,0,6]},{"op":"actor_select","args":[0,57,0,0,0,0,6]},{"op":"delay","args":[10]},{"op":"play_music","args":[35,1]},{"op":"delay","args":[10]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&曹奂\n为什么？为什么连个黄门侍郎你都不\n放过？\n&钟会\n如果陛下早做决断，就不会有今天的事情\n发生了。\n&曹奂\n呜呜呜呜呜…"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,4,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二六四年三月，曹魏皇帝曹奂将皇位禅让给晋王司马炎，",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["从高平陵政变后名存实亡的曹魏宣告灭亡。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["自二二零年曹丕篡汉建立，二六四年被司马炎篡夺灭亡，立国共四十五年。",0,0,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[96,51,29,2,0]},{"op":"actor_appear","args":[70,51,39,0,0]},{"op":"actor_appear","args":[588,41,52,1,0]},{"op":"actor_appear","args":[587,41,57,1,0]},{"op":"actor_appear","args":[199,41,62,1,0]},{"op":"actor_appear","args":[102,41,67,1,0]},{"op":"actor_appear","args":[107,41,72,1,0]},{"op":"actor_appear","args":[100,41,77,1,0]},{"op":"actor_appear","args":[99,65,52,3,0]},{"op":"actor_appear","args":[98,65,57,3,0]},{"op":"actor_appear","args":[117,65,62,3,0]},{"op":"actor_appear","args":[663,65,67,3,0]},{"op":"actor_appear","args":[97,65,72,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["以晋代魏"]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"actor_action","args":[96,6]},{"op":"dialog","args":["&司马炎\n臣愿接受陛下的托付，拯救天下于危难\n之间。\n&司马炎\n虽然臣万般无奈，但实在是情况危急，\n吴、蜀等盗匪集团猖獗，不得不在此时\n接受这样的重任。"]},{"op":"actor_action","args":[96,17]},{"op":"dialog","args":["&司马炎\n现在就改国号为“晋”，改元“泰始”，\n希望能够就此平定分裂混乱的天下。\n&司马炎\n在天下平定以前，请您就先委屈在洛阳的\n金墉城吧。\n&司马攸\n（大哥也太狠了吧，这个金墉城，过去\n虽然是明皇帝所建，具有防卫效果的要塞\n，现在早就已经是座高级政治监狱了。）\n&曹奂\n……\n&贾充\n咳…难道你忘记要做什么了？\n&曹奂\n臣叩谢皇上圣恩。\n&司马炎\n如此大礼，朕实在是受不起呀。"]},{"op":"actor_action","args":[96,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[70,0,2]},{"op":"actor_move","args":[0,99,0,51,44,0]},{"op":"actor_action","args":[99,6]},{"op":"dialog","args":["&司马孚\n陛下，老臣此生都是魏臣。不管天下人\n如何背弃大魏，老臣都愿意当大魏最后\n的纯臣。\n&曹奂\n太傅…\n&司马孚\n老臣无力，无法阻止大魏被篡夺。至少\n，让老臣去送陛下最后一程吧。\n&司马炎\n（这个叔祖实在是太不给朕面子了，\n不过不管怎么样，他终究是我叔祖，\n本朝以孝治天下，怎能不尊敬他呢？）\n&司马攸\n（大哥，您到底做了什么样的事情？\n为什么到最后还要学曹家父子呢？\n您不怕到时候别人又有样学样？）"]},{"op":"actor_move","args":[0,70,0,53,99,2]},{"op":"actor_move","args":[0,99,0,53,99,2]},{"op":"actor_select","args":[0,70,0,0,0,0,6]},{"op":"actor_select","args":[0,99,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马炎\n现追封祖父为宣皇帝，伯父为景皇帝。\n父亲为文皇帝。而母亲升任皇太后。\n&司马炎\n三叔祖为安平王，四叔父司马亮为\n扶风王。\n&司马炎\n叔父司马胄为琅琊王、堂叔司马望为\n河内王、皇弟司马攸为楚王。\n&司马炎\n叔祖司马孚为太宰、郑冲为太傅、王祥为\n太保、石苞为大司马、司马望为大将军、\n贾充为车骑将军、陈骞为骠骑将军。\n&司马炎\n荀顗为司空、王沈为太尉、荀勖为司徒。\n其他人也各有封赏。\n&贾充\n（本来以为会有钟会的名字，怎么会\n没有呢？）\n&钟会\n（陛下早就已经让我当到侍中兼中书令，\n新的朝代有新的政体，侍中和中书省才是\n才是真正能够进行决策的地方。）\n&荀勖\n（该死的钟会，害我只能当个有地位没\n实权的司徒。你夺我凤凰池呀！）"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[571,53,99,0,0]},{"op":"actor_move","args":[0,571,0,53,52,0]},{"op":"actor_action","args":[571,6]},{"op":"dialog","args":["&文官\n陛下，大事不好了！河北军叛变了，邺城\n那边也树立起大魏的旗帜。\n&文官\n原河北都督何曾和邺城都督山涛都跟著\n造反，现在只怕邺城以北的各郡都会跟\n着脱离大晋。"]},{"op":"dialog","args":["&司马望\n怎么会这样？！河北居然造反了？\n&司马炎\n不用担心，这些余孽的造反早就在朕的\n意料之中。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[107,6,0]},{"op":"dialog","args":["&钟会\n河北军虽然人数众多，且人质都在邺城\n，无法对他们产生牵制作用。\n&钟会\n但是大魏多年来的强化中央政策，让洛阳\n拥有可以匹敌全天下的战力。区区河北军\n能和我们为敌？\n&钟会\n当年毌丘俭拥兵十万，照样被击破。\n诸葛诞拥有死士和吴贼援军，照样城破\n身亡。\n&钟会\n如今河北不过后方，将士素质远不能和\n淮南相比，如何动摇我大晋江山？\n&司马炎\n正是如此，我们大晋的天下还是很稳的。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[96,17]},{"op":"dialog","args":["&司马炎\n河内王，命您率兵十万前往北方迎敌，\n必要一战破敌，接著攻破邺城。\n&司马炎\n皇叔，既然任命您担任河内王，该知道\n朕对您的期望。"]},{"op":"actor_face","args":[98,6,0]},{"op":"dialog","args":["&司马望\n臣一定竭尽所能击垮叛军。\n&司马望\n（行吗？十万人的军饷哪凑得齐，该不会\n要我自掏腰包吧。）\n&司马炎\n扶风王，命你都督关中诸军事，立刻前往\n长安监视蜀人动向。\n&司马炎\n朕已经命骠骑将军随后赶到长安配合行动\n，靠着重整后的关中部队，一定可以击破\n张狂的蜀人。"]},{"op":"actor_face","args":[663,0,0]},{"op":"dialog","args":["&司马亮\n是！\n&司马炎\n朕还有道密令，到长安之后你再开启。\n&贾充\n（陛下果然延续过去文皇帝的政策，重用\n同姓亲族担任都督。不过他没有想过，\n这些亲族能打仗的没几个？）\n&贾充\n（先不说那个简朴打仗的司马望，那个\n司马亮哪有带过兵，叫他和姜维对阵，\n根本是要他的命。）\n&贾充\n（现在唯一有指挥大部队经验的是司马孚\n，但我看他根本无心于本朝，看来是更\n不能指望了。）\n&贾充\n（这样下去行吗？为什么钟会这家伙都\n不坑一声？）\n&钟会\n（就算知道是错误的决定又如何？既然\n司马家摆明只相信自己人，我又何必多\n嘴？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,62,65535]},{"op":"actor_appear","args":[24,43,46,2,0]},{"op":"actor_appear","args":[112,53,46,2,0]},{"op":"actor_appear","args":[68,48,46,2,0]},{"op":"actor_appear","args":[258,41,76,0,0]},{"op":"actor_appear","args":[259,46,76,0,0]},{"op":"actor_appear","args":[260,51,76,0,0]},{"op":"actor_appear","args":[261,60,76,0,0]},{"op":"actor_appear","args":[262,65,76,0,0]},{"op":"actor_appear","args":[263,46,81,0,0]},{"op":"actor_appear","args":[265,51,81,0,0]},{"op":"actor_appear","args":[266,60,81,0,0]},{"op":"actor_appear","args":[267,65,81,0,0]},{"op":"actor_appear","args":[268,46,86,0,0]},{"op":"actor_appear","args":[269,51,86,0,0]},{"op":"actor_appear","args":[270,60,86,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["曹魏的复生"]},{"op":"place_name","args":["邺城 铜雀台"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹芳\n朕…朕在十年前被贼人司马师废黜，当时\n朕年幼无力，眼见贼人一步步进逼却无力\n反抗。\n&曹芳\n现在朕不一样了，朕有各位的相助，可以\n和司马家对决了。\n&曹芳\n朕不敢想像能有武帝之功，只希望不愧对\n明皇帝选朕继承大统的期望，重振朝纲，\n复兴大魏！讨伐篡逆司马氏！\n&曹绫\n（说得不错，虽然有些紧张，但已经比\n当年好很多。这些年在河内受了不少苦\n，似乎也将皇上磨练了一番。）\n&步兵1\n复兴大魏！\n&步兵2\n讨伐司马家！\n&曹绫\n（虽说河北军人数不少，也无军心动摇\n之虞，但是能否和精锐的中军对抗还是\n未知数。）"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[83,55,98,0,0]},{"op":"actor_move","args":[0,83,0,55,78,0]},{"op":"actor_action","args":[83,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&费曜\n公主，还记得我吗？\n&曹绫\n费叔叔？！\n&费曜\n过去大司马总对我说，能支撑曹家的只有\n公主您，今日果然应验了。"]},{"op":"actor_action","args":[83,6]},{"op":"dialog","args":["&费曜\n老奴费曜忍气吞声十五年，今日将加入\n大魏讨伐司马家的义军。\n&曹绫\n费叔叔，有你加入更是让人振奋呀。\n&费曜\n我带了能解决公主烦恼的礼物。\n&曹绫\n礼物？\n&费曜\n这一切都要感谢国让，如果大魏能复兴，\n请公主一定再好好答谢他。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[27]},{"op":"change_scene","args":[2,65535,65535,63,65535]},{"op":"actor_appear","args":[248,52,63,1,0]},{"op":"actor_appear","args":[83,58,63,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["十五年前"]},{"op":"place_name","args":["并州 魏军营帐外"]},{"op":"actor_action","args":[83,3]},{"op":"dialog","args":["&费曜\n我一定要报仇！这个司马懿简直就是\n混帐！居然敢将大司马一家屠灭。\n&田豫\n不，请你先等等，你认为凭你手上的军队\n足够对抗司马家？连大将军都认为不敌而\n屈服了不是吗？\n&费曜\n就算这样又如何！就算一死也要和司马懿\n拚了。\n&田豫\n那样就太蠢了，你认为你真的有机会\n起兵？"]},{"op":"actor_action","args":[83,0]},{"op":"dialog","args":["&田豫\n征北将军程喜是个墙头草小人，你认为\n你有什么不轨的举动，他会怎么做？\n&费曜\n解决我向司马懿邀功？\n&田豫\n完全正确，别忘记杜恕的下场，他就是\n被程喜那个小人陷害的。\n&田豫\n现在你应该做的就是保全自己，保持沉默\n让司马懿忘了你。\n&费曜\n这样怎么行，这样我还对得起大司马？\n&田豫\n别急，你看看外面这些都督有哪个人起事\n？司马懿虽然诛杀大将军一家，但却没有\n明显的不轨举动。\n&田豫\n不过我可不认为司马懿是什么忠臣，迟早\n他的狐狸尾巴会露出来。\n&田豫\n你应该等到他不臣的举动出现，起义才有\n大义名分。\n&田豫\n不过我要是你的话，我会忍到力量积蓄够\n为止，任何的贸然起兵都只会落得被个别\n击破而已。\n&费曜\n你要我怎么做？\n&田豫\n现在普天下能够对抗中军的部队并不多，\n就算是蜀吴有相抗衡的部队，但是数量也\n远远不如。\n&田豫\n都督军都不敢保证能赢，更何况还是\n州郡兵。\n&田豫\n然而我在并州这里看见了希望。\n&田豫\n你看看这五部匈奴，记得在四百多年前，\n这些人还曾经把汉高祖皇帝围困在白登山\n不是吗？\n&费曜\n原来如此，用匈奴人来对抗司马家一手\n掌控的中军？\n&田豫\n是的。不过要记住，这是万不得已的\n手段。\n&费曜\n为什么呢？\n&田豫\n我怕匈奴人的战力会远超过我们想像，\n毕竟他们是一群自以为自己是猫的老虎。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,62,65535]},{"op":"actor_appear","args":[24,43,46,2,0]},{"op":"actor_appear","args":[68,48,46,2,0]},{"op":"actor_appear","args":[112,53,46,2,0]},{"op":"actor_appear","args":[83,55,78,0,0]},{"op":"actor_appear","args":[258,41,76,0,0]},{"op":"actor_appear","args":[259,46,76,0,0]},{"op":"actor_appear","args":[260,51,76,0,0]},{"op":"actor_appear","args":[261,60,76,0,0]},{"op":"actor_appear","args":[262,65,76,0,0]},{"op":"actor_appear","args":[263,46,81,0,0]},{"op":"actor_appear","args":[265,51,81,0,0]},{"op":"actor_appear","args":[266,60,81,0,0]},{"op":"actor_appear","args":[267,65,81,0,0]},{"op":"actor_appear","args":[268,46,86,0,0]},{"op":"actor_appear","args":[269,51,86,0,0]},{"op":"actor_appear","args":[270,60,86,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"place_name","args":["邺城 铜雀台"]},{"op":"title_text","args":["曹魏复兴"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&陈泰\n原来如此，这个田豫果然是名不虚传，\n难怪刘备会感叹不能和他共事了。"]},{"op":"actor_action","args":[83,6]},{"op":"dialog","args":["&费曜\n我从并州那里带来一万匈奴兵，战斗力\n之强，绝对不输虎豹骑。\n&费曜\n不过匈奴王刘豹有交代，说他为了怕洛阳\n那边起疑心，所以他把嫡子送去洛阳。\n&费曜\n若是最后行动成功，而他嫡子又侥幸没被\n杀害的话，请从洛阳将他救出。"]},{"op":"actor_face","args":[24,0,1]},{"op":"dialog","args":["&曹绫\n圣上，您看看该怎么回应呢？\n&曹芳\n这点朕当然答应，而且朕事后还会重重\n赏赐匈奴部落。\n&曹绫\n（匈奴…果然是个强大的外援。话说回来\n，姜维的出兵也是计画成功的关键，这时\n他应该已经往凉州进兵了吧。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,32,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二六四年三月，曹魏余众在废帝曹芳和东乡公主曹绫呼召下起兵。",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["何曾麾下的河北军也同时宣布倒戈。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["司马炎命令河内王司马望率领十万大军前去邺城平乱，",0,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["而曹魏则派出陈泰出兵迎击，双方在冀州黎阳开始交战。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[40]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[645,34,54,1,0]},{"op":"actor_appear","args":[149,48,43,2,0]},{"op":"actor_appear","args":[150,53,43,2,0]},{"op":"actor_appear","args":[151,58,43,2,0]},{"op":"actor_appear","args":[148,63,43,2,0]},{"op":"actor_appear","args":[106,48,69,0,0]},{"op":"actor_appear","args":[718,53,69,0,0]},{"op":"actor_appear","args":[54,58,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["邓艾战略"]},{"op":"place_name","args":["祁山 晋军营帐"]},{"op":"actor_face","args":[106,6,3]},{"op":"dialog","args":["&师纂\n现在晋王已经接受禅让，天下已经变成\n大晋了。\n&师纂\n我们身为臣属的，不应该表示祝贺？\n&邓艾1\n你还真有这种心情？你知道现在陇西状况\n有多糟糕？\n&牵弘\n胡刺史战死，整个凉州都被宣告失陷，\n接下来蜀人随时会往东进攻。\n&邓艾1\n嗯…我早就提醒胡烈要注意，不要去招惹\n鲜卑人，他还是当耳边风。"]},{"op":"actor_face","args":[106,0,0]},{"op":"actor_face","args":[148,0,3]},{"op":"dialog","args":["&胡渊\n邓艾！不准污蔑我爹，他可是为国捐躯，\n不像你这战败只知逃跑的胆小鬼。\n&邓艾1\n我说的都是事实，要是不服气，你随时\n可以去找蜀人拚命。不过，这也只是愚\n蠢的送死而已。"]},{"op":"actor_face","args":[149,0,3]},{"op":"dialog","args":["&王颀\n现在该怎么办？难道眼睁睁看着祁山以西\n的地方丢光？\n&邓艾1\n不用担心，就如同我之前说的，丢掉这些\n地方，对我们影响并不严重。但如果浪费\n兵力去防守，才是正中敌人下怀。\n&邓艾1\n我们无法有效统治祁山以西，蜀人同样也\n不行。最后还是得靠场关键性的会战才能\n决定祁山以西之地的归属。\n&王颀\n我们不妨向洛阳求援如何？洛阳方面如果\n知道这实际情况，一定会派出援军。\n&邓艾1\n我早就已经向洛阳求援，但是似乎因为\n之前那边忙著争权和夺位，根本就不把\n我的上书当一回事。\n&王颀\n听说新任的关中都督已经上任，我们不妨\n向他求援？\n&邓艾1\n也只能这样做了…但是，如果对方不肯把\n指挥权交给我，只怕这仗不好打。\n&师纂\n都打过大败仗了，还那么有自信，\n真不知道这自信是哪来的。\n&邓艾1\n（姜维，难道过去你都是在这样的情况下\n做事？如果你在无后顾之忧的情况下，\n是不是会有超越我的表现？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[11]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[96,51,29,2,0]},{"op":"actor_appear","args":[128,49,52,0,0]},{"op":"actor_appear","args":[129,55,52,0,0]},{"op":"actor_appear","args":[588,41,47,1,0]},{"op":"actor_appear","args":[587,41,52,1,0]},{"op":"actor_appear","args":[199,41,57,1,0]},{"op":"actor_appear","args":[102,41,62,1,0]},{"op":"actor_appear","args":[107,41,67,1,0]},{"op":"actor_appear","args":[100,41,72,1,0]},{"op":"actor_appear","args":[97,65,47,3,0]},{"op":"actor_appear","args":[549,65,52,3,0]},{"op":"actor_appear","args":[670,65,57,3,0]},{"op":"actor_appear","args":[720,65,62,3,0]},{"op":"actor_appear","args":[721,65,67,3,0]},{"op":"actor_appear","args":[226,65,72,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["文鸯复出"]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"dialog","args":["&司马炎\n听闻两位卿家武勇过人，想要重新起用\n你们。"]},{"op":"actor_action","args":[128,6]},{"op":"dialog","args":["&文鸯\n陛下真瞧得起我，实在是不胜感激。\n看来陛下果然还记得当年之事。\n&司马炎\n当年之事？\n&文鸯\n当年乐嘉之战，我一个人在数十万中军\n杀进杀出，视大军如草芥。"]},{"op":"actor_action","args":[97,0]},{"op":"dialog","args":["&司马攸\n文鸯！你放肆，朝廷不问你当年冒犯景帝\n之罪已经是恩惠，你还敢再提起？\n&文鸯\n已经发生的事情就是已经发生，我又何须\n遮遮掩掩？\n&文虎\n（二哥，您为什么要这样做？）\n&司马炎\n无妨，朕最欣赏这样直言不讳的人。"]},{"op":"actor_action","args":[97,0]},{"op":"dialog","args":["&司马炎\n（这文鸯真不是东西，难怪爹当年不肯\n重用他。）\n&司马炎\n朕接到邓艾在陇西的军情，说现在雍凉\n情况紧急，朕决定要派你们率军援救。\n&司马炎\n不知道给你两千武卫营部队够吗？\n&冯紞\n（把你们丢到那鬼地方，你们注定坐\n冷板凳坐一辈子。）\n&任恺\n（才两千？更何况还是因为亲魏色彩浓厚\n而遭到打压的武卫营。）\n&文鸯\n陛下，两千人是否太多了？洛阳的守备\n难道不需要人？\n&文鸯\n我只要五百已足。\n&司马炎\n好，文卿家自信过人，朕非常欣赏。\n&司马炎\n（只会说大话，你就去死吧！）\n&文虎\n（二哥？！为什么要故意得罪皇上？）\n&文鸯\n（在这个地方，等我们有仗打的时候，\n都要准备亡国了。）\n&文鸯\n（反而到陇西那边，可以和蜀地猛将们\n交手。听闻姜维是现存唯一和赵云交过手\n的猛将，我很想见见他。）\n&文虎\n（原来如此，二哥永远是对的。）\n&文鸯\n（放心吧，我已经留了点礼物给司马炎，\n如果他是个人物，就会高兴收下这礼物。\n反之，我们离开洛阳也不用觉得可惜。）"]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,128,0,53,99,2]},{"op":"actor_move","args":[0,129,0,53,99,2]},{"op":"actor_select","args":[0,128,0,0,0,0,6]},{"op":"actor_select","args":[0,129,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&贾充\n这两兄弟算什么东西，居然敢摆出这种\n倨傲态度，和邓艾那浑球送作堆正好。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[721,0,0]},{"op":"dialog","args":["&魏舒\n陛下，这两兄弟虽然态度倨傲，却是从\n张文远、许仲康等将军后最强的武将。\n&冯紞\n笑死人了，光听他们吹牛就行吗？\n&魏舒\n你们还是不明白呀，臣虽然是学武出身\n，但刚才文鸯做的事情臣可也是很勉强\n才看得到。\n&司马炎\n什么？！这大殿的石阶居然…\n&魏舒\n陛下，他光是空手就可以破坏这坚硬无比\n的石阶，而且还没有人知道他什么时候做\n的。\n&魏舒\n这样的人至少应该要留在身边护卫陛下。"]},{"op":"actor_action","args":[96,2]},{"op":"dialog","args":["&司马炎\n够了，我们大晋要的是将才，不是舞刀\n弄枪的武夫。\n&司马炎\n（文鸯！你在朕面前的所作所为，朕会记\n一辈子。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[69]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,0,0]},{"op":"actor_appear","args":[52,39,61,1,0]},{"op":"actor_appear","args":[55,39,56,1,0]},{"op":"actor_appear","args":[652,39,51,1,0]},{"op":"actor_appear","args":[42,39,46,1,0]},{"op":"actor_appear","args":[40,65,61,3,0]},{"op":"actor_appear","args":[47,65,56,3,0]},{"op":"actor_appear","args":[257,65,51,3,0]},{"op":"actor_appear","args":[43,65,46,3,0]},{"op":"actor_appear","args":[0,52,61,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["上表北伐"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n陛下，贼首司马昭已在上次作战中伏法，\n我军的凉州攻势也进行顺利，将祁山以西\n的各郡大致纳入势力范围。"]},{"op":"actor_face","args":[47,6,2]},{"op":"dialog","args":["&董厥\n既然如此，我们应该即刻派官去治理。\n&姜维\n此举万万不可。"]},{"op":"actor_face","args":[47,0,3]},{"op":"dialog","args":["&姜维\n大汉如果要统治陇西各郡，就会增加和\n当地汉人与外族的摩擦。一旦发生冲突\n，我们就得派兵去平乱。\n&姜维\n纵然平乱成功，我们也会消耗大量国力\n。而平乱失败，则之前的成果也将化为\n乌有。\n&樊建\n那这样，我们辛辛苦苦攻下陇西各郡是\n为何？\n&姜维\n一来可以制造一个真空的缓冲地带，若是\n曹贼要反攻，也会面临是否要治理陇西的\n选择压力。\n&姜维\n二来和陇西势力交好，使该地成为亲大汉\n的友好势力，也可以获得兵员与物资的补\n充，减轻我大汉国力的负担。\n&刘禅\n一切就照大将军的意思吧。\n&姜维\n现在贼将邓艾把部队集中在祁山，大有要\n和我军决战之意。此时我军应该也要集中\n战力，和邓艾对决。\n&姜维\n如果可以攻破战略要地祁山，则我军可\n完全确保凉州的安全，更可以东进武功\n，直取长安。\n&姜维\n长安一破，则只要再攻破潼关，洛阳就\n近在眼前。\n&谯周\n我不认为我们有必要如此贪心，现在拿下\n陇西四郡已经是很大的战果了。万一又败\n给邓艾，岂不是重蹈当年段谷覆辙。\n&黄崇\n我也感觉有点不放心，不知道大将军可否\n再考虑一下？\n&姜维\n我明白大家的顾虑，但是现在邓艾的陇西\n兵团在上次入侵中元气大伤，洛阳的援军\n也暂时未到的情况下，这是战胜的机会。\n&姜维\n我承认只要邓艾有优势兵力的情况下，\n绝对是无法战胜。所以更要把握他战力\n低下的时候，给他致命一击。\n&诸葛瞻\n大将军所言有理，上次在江油和邓艾的\n交锋，就是乘他之危才侥幸取胜。类似\n的机会并不多，得好好把握。\n&董厥\n（思远怎么回事？为什么变得这么挺\n姜维？）\n&刘禅\n就准卿所奏，让大将军自由调派军队\n北伐吧。"]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&刘禅\n这次大将军功苦劳高，让大汉获得空前\n的胜利，朕就将先帝的御剑赏赐给你。"]},{"op":"actor_move","args":[0,50,0,52,65,0]},{"op":"delay","args":[5]},{"op":"get_item","args":[43,0,0,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n谢陛下！"]},{"op":"actor_action","args":[0,0]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,50,0,59,73,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n另外，臣有个提议，也请陛下考虑一下。\n&姜维\n益州人长期受到外来政权统治，从刘焉\n父子以来就饱受压迫。\n&姜维\n益州人由于感受到剥夺感，所以抗拒和\n大汉合作是可以理解的。平心而论，\n我们确实亏欠他们很多。\n&姜维\n所以，如果我们能收复洛阳，是否应该\n考虑即刻还都，让所有外来人士都回归\n本籍，还给益州人生存空间？"]},{"op":"actor_action","args":[52,0]},{"op":"dialog","args":["&阎宇\n这什么话？说的好像我们是外来的侵略者\n一样！这块土地是大汉的！凭什么要我们\n让出来！\n&董厥\n这太奇怪了，我们又不是没有照顾益州人\n，都已经让他们当到大官了，还有什么好\n不满的。\n&黄崇\n大将军真是了不起！居然把我们益州人的\n心声说出来了。不是说让我们任职就算是\n施恩，你们对我们的压迫可多了。\n&李球\n真想不到…真想不到…先帝做不到的事情\n、丞相做不到的事情，居然由大将军来\n完成。"]},{"op":"actor_face","args":[42,0,2]},{"op":"dialog","args":["&黄崇\n陛下，这是我们益州人一致的心愿。\n&黄崇\n为了完成这样的梦想，我们会竭尽心力\n来协助北伐大业。\n&谯周\n（这样的空言值得相信？年轻人终究是\n年轻人，太天真了。）\n&谯周\n（也该想想，现在我们只有益州，益州人\n还勉强可以获得一定程度的任用。）\n&谯周\n（等到真的打下洛阳，北方人士开始进入\n朝廷时，我们益州人被边缘化的情形恐怕\n会更严重。）\n&黄皓\n大将军准备要和益州人连成一气逼宫？\n&刘禅\n黄皓，闭嘴。\n&刘禅\n朕决定接受大将军的提案，只要能够光复\n洛阳，朕没有不还都的道理，更没有长期\n霸占益州的打算。\n&阎宇\n陛下！\n&刘禅\n不过，这也是在光复洛阳的前提上，\n不是吗？\n&郤正\n（伯约，这可是政治的豪赌呀。只是你\n这样做，不管是否成功拿下洛阳，等著\n你的，都会是恐怖的命运。）\n&诸葛瞻\n（若不是姊姊提早告诉我，说姜维会有\n这样的想法，恐怕我也会跳出来批判。）\n&诸葛瞻\n（你这家伙到底在想什么呢？为了争取\n益州人支持要玩这么大？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[27]},{"op":"change_scene","args":[2,65535,65535,26,65535]},{"op":"actor_appear","args":[0,42,54,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["刘谌与姜维"]},{"op":"place_name","args":["宫门 "]},{"op":"delay","args":[8]},{"op":"actor_move","args":[0,0,0,58,54,1]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&刘谌\n大将军！"]},{"op":"delay","args":[8]},{"op":"actor_appear","args":[60,42,54,1,0]},{"op":"wait_frame","args":[]},{"op":"delay","args":[8]},{"op":"actor_move","args":[0,60,0,53,54,1]},{"op":"delay","args":[8]},{"op":"actor_action","args":[60,6]},{"op":"dialog","args":["&刘谌\n终于见到你了…\n&姜维\n请问你是…\n&刘谌\n我名刘谌，被封为北地王，是陛下的\n第五个儿子。"]},{"op":"actor_action","args":[60,0]},{"op":"actor_face","args":[0,6,3]},{"op":"dialog","args":["&姜维\n幸会幸会，在下也约略听过您，据说您的\n勇烈可比先帝。\n&刘谌\n那是众人的谬赞，我只是向往先帝和丞相\n的理想，希望能为北伐大业多尽份心力。"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&姜维\n姜维马上就要回去北方主持北伐大业，\n还请北地王您等候胜利的好消息。\n&刘谌\n我真恨自己的年纪和本事，要是能有祖父\n的十分之一，现在早就陪大将军上战场。"]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&刘谌\n大将军，或许朝中还有很多人误解你，\n但是我一直是相着著你。\n&刘谌\n你一路为大汉作战数十年，坚持着先帝\n和丞相的理想，不管遇到什么困难都不\n放弃。\n&刘谌\n如果没有你，只怕现在大汉早就放弃进取\n之志，变成一个没有理想的割据政权。\n&姜维\n北地王您太过奖了，姜维只是照自己的\n想法，用自己认为最好的方式守护大汉\n而已。"]},{"op":"actor_action","args":[60,6]},{"op":"dialog","args":["&刘谌\n刘谌这就祝大将军旗开得胜，并且在未来\n还都洛阳之时，期待和大将军在那相见。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n也请北地王多保重。"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[69]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,0,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二六四年四月，蜀汉皇帝刘禅批准北伐，并且下旨蜀汉全国进行总动员，",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["包括南中部队和永安驻防军，总数超过六万的军队，全部往汉中集结。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["自从刘备出征汉中以来从未有过的大攻势，现在再度重现。",0,0,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[69]},{"op":"change_scene","args":[2,65535,65535,23,65535]},{"op":"actor_appear","args":[0,39,38,2,0]},{"op":"actor_appear","args":[23,24,47,0,0]},{"op":"actor_appear","args":[17,29,47,0,0]},{"op":"actor_appear","args":[15,34,47,0,0]},{"op":"actor_appear","args":[12,39,47,0,0]},{"op":"actor_appear","args":[9,44,47,0,0]},{"op":"actor_appear","args":[4,49,47,0,0]},{"op":"actor_appear","args":[22,54,47,0,0]},{"op":"actor_appear","args":[13,59,47,0,0]},{"op":"actor_appear","args":[3,64,47,0,0]},{"op":"actor_appear","args":[11,24,52,0,0]},{"op":"actor_appear","args":[21,29,52,0,0]},{"op":"actor_appear","args":[2,34,52,0,0]},{"op":"actor_appear","args":[1,39,52,0,0]},{"op":"actor_appear","args":[20,44,52,0,0]},{"op":"actor_appear","args":[10,49,52,0,0]},{"op":"actor_appear","args":[8,54,52,0,0]},{"op":"actor_appear","args":[18,59,52,0,0]},{"op":"actor_appear","args":[16,64,52,0,0]},{"op":"actor_appear","args":[14,24,57,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["北伐誓师"]},{"op":"place_name","args":["汉中"]},{"op":"actor_action","args":[13,6]},{"op":"dialog","args":["&霍弋\n南中督霍弋，率南中军前来支援。\n&张嶷\n南中那边有孟琰等南中大族帮忙防守，\n加上和交州吕兴关系良好，可以不用担心\n东吴的问题。\n&姜维\n这样我就放心了。和南中军的弟兄们分开\n已久，真的很想念你们呀。"]},{"op":"actor_face","args":[23,0,1]},{"op":"dialog","args":["&张星彩\n是呀，我也很想念那个关索…想到想揍他\n一顿。\n&花鬘\n这点，还不需要劳驾皇后你来的啦，\n我天天都在南中揍他。\n&关索\n我真命苦…"]},{"op":"actor_face","args":[23,0,0]},{"op":"actor_action","args":[21,6]},{"op":"dialog","args":["&罗宪\n巴东督罗宪，率领永安军队前来支援。\n&姜维\n我已经听过令则在永安的英勇事迹，\n能和你共事，实在是太好了。\n&罗宪\n永安那边已经让杨宗暂代太守，诸葛将军\n和糜将军也在那支援。\n&宗预\n伯约不用担心，东吴目前暂时忙于平乱，\n武陵蛮的问题还是困扰的他们。\n&宗预\n等到乱平之时，我们大概也已经拿下洛阳\n，到时他们绝对是朝向已经衰弱的贼营\n攻击。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n李球、黄崇等益州人也在一瞬间愿意支持\n北伐，这其实都要归功于伯恭的提案。\n&张翼\n不，能够接受这样的提案，你才真是了\n不起。\n&张翼\n要知道，若是一个不小心，就会引起朝中\n许多大臣和陛下的反感。\n&姜维\n纵然如此，我认为对的事情就该去做。"]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n现在贼势已衰，北伐中原大有可为，故\n在此集中我大汉所有的力量，只求光复\n故土！\n&向充\n（大将军本来要在丞相墓前誓师，幸好\n诸葛姑娘劝阻了他。不过把皇后摆在底下\n，其他人会怎么想呢？）\n&向充\n（老师，为什么一句话都不说呢？究竟\n您在想什么？为什么不能告诉我？）\n&宁随\n………\n&来忠\n（向充果然是善良的家伙，要是我就不会\n这么想了。我们大汉不能永远笼罩在丞相\n的阴影下，但是其他人可不这么想。）\n&来忠\n（早晚有一天，大将军会知道自己最大的\n敌人不是邓艾或是司马家，而是围绕自己\n身边的人呀。）"]},{"op":"actor_action","args":[0,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&廖化\n伯约，你讨好益州人，想在光复洛阳后，\n将我们外地人迁出我可以理解。\n&廖化\n但是你直接向皇上进言，这是大将军可以\n插手的事情？你这样还算是人臣？\n&姜维\n元俭…我的所作所为确实是踰矩，但是\n陛下也愿意接受，不是吗？\n&廖化\n若是陛下不肯接受呢？你要逼宫？效法\n曹操或是董卓？\n&姜维\n说实话…我不知道…但那一瞬间，我确实\n没有考虑过陛下的想法…甚至…\n&诸葛果\n主公，这也是所谓的选项之一，请不要\n任意抛弃自己的想法，任何想法都是可\n贵的。\n&诸葛果\n天下不是陛下一人的，而是大汉的天下。\n只要主公认为是对的，就请放心去做。\n&杨兰\n姜维，或许现在想不到，但是不久的将来\n，你应该可以找到自己的答案。\n&廖化\n也罢，就让我继续观察你的所作所为吧，\n若是你有任何一丝不轨的企图，我一定会\n第一个跳出来铲除你。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[17,0,1]},{"op":"dialog","args":["&廖化\n赵将军，身为子龙将军的后代，你不也该\n有所表示？\n&赵统\n………给我时间考虑好吗？"]},{"op":"actor_face","args":[17,0,0]},{"op":"actor_action","args":[4,6]},{"op":"dialog","args":["&句扶\n不论如何，我都会支持你的。\n&句扶\n这不只是为了益州这块土地，更因为你是\n我值得效忠的对象。"]},{"op":"actor_action","args":[3,6]},{"op":"dialog","args":["&柳隐\n没错，我和小句一样，并不在乎什么\n益州人的地位，只在乎你是否能继续\n带领我们。\n&马隆\n（这里还真是有趣，形形色色不同的想法\n混杂于其中，却还能一致对外，看来我是\n来对了地方。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[23,46,45,2,0]},{"op":"actor_appear","args":[17,51,45,2,0]},{"op":"actor_appear","args":[15,56,45,2,0]},{"op":"actor_appear","args":[11,61,45,2,0]},{"op":"actor_appear","args":[4,66,45,2,0]},{"op":"actor_appear","args":[3,71,45,2,0]},{"op":"actor_appear","args":[2,76,45,2,0]},{"op":"actor_appear","args":[9,46,66,0,0]},{"op":"actor_appear","args":[1,51,66,0,0]},{"op":"actor_appear","args":[5,56,66,0,0]},{"op":"actor_appear","args":[8,61,66,0,0]},{"op":"actor_appear","args":[10,66,66,0,0]},{"op":"actor_appear","args":[18,71,66,0,0]},{"op":"actor_appear","args":[14,76,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["命运转捩点"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"if","cond":"test_resource","args":[2,55,0],"end":23},{"op":"set_flag","args":[920,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_resource","args":[2,50,1],"end":26},{"op":"set_flag","args":[921,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_resource","args":[2,50,2],"end":29},{"op":"set_flag","args":[922,1]},{"op":"endif","args":[]},{"op":"actor_face","args":[8,6,3]},{"op":"dialog","args":["&来忠\n一切正如大将军预料，邓艾的军队仍然\n停留在祁山，看来他是打算在那里决战。\n&姜维\n不愧是邓艾，局势判断还是那么精确。\n以祁山的开阔地形，确实是决战的地方。\n&姜维\n（问题还是在于，邓艾目前手上有多少\n兵马。）\n&姜维\n（如果只有陇西军团，那么我军还可以\n拥有人数优势。但如果加上关中军团…）\n&姜维\n（看来就算是司马昭死亡，要北伐完全\n成功还是得经过一番苦战，两边的基础\n实力相差还是很悬殊。）"]},{"op":"actor_face","args":[8,0,0]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[566,92,54,3,0]},{"op":"actor_move","args":[0,566,0,48,54,3]},{"op":"actor_action","args":[566,6]},{"op":"delay","args":[5]},{"op":"dialog","args":["&士兵01\n大将军，不得了了。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n什么事情慌慌张张的。\n&士兵01\n见鬼了！"]},{"op":"actor_action","args":[3,2]},{"op":"dialog","args":["&柳隐\n说清楚点！"]},{"op":"actor_action","args":[3,0]},{"op":"dialog","args":["&士兵01\n已故的车骑将军居然来到营前，还带了\n个大美女说要见大将军。\n&姜维\n之前事情太多忘记和大家说了。仲权其实\n没有死，一直躲在洛阳由他女婿羊祜保护\n着。\n&张星彩\n原来如此，我就知道车骑将军他没那么\n容易死。\n&杨兰\n等一下，美女是怎么回事？"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[566,6,1]},{"op":"dialog","args":["&士兵01\n小人也不是很清楚，总之就是个美到\n让人不敢多看的女子。\n&姜维\n辛苦了，你先下去吧。"]},{"op":"actor_move","args":[0,566,0,92,54,1]},{"op":"actor_select","args":[0,566,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&姜维\n我大概知道是谁了…我就去亲自迎见\n他们吧。"]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":57},{"op":"actor_face","args":[2,3,3]},{"op":"dialog","args":["&杨兰\n我要跟你一起去。\n&姜维\n不需要吧，都是我们认识的人，不会有\n危险的。"]},{"op":"actor_face","args":[2,0,1]},{"op":"dialog","args":["&杨兰\n不，很危险，而且是非常危险。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":61},{"op":"actor_face","args":[1,0,3]},{"op":"dialog","args":["&诸葛果\n可以的话，主公请允许果一同前往。\n&姜维\n为什么呢？\n&诸葛果\n这是果的请求。\n&姜维\n不知道你为什么这么坚持，好吧…\n&袁綝\n（诸葛果的斗争心被点燃？真难得呀。）"]},{"op":"endif","args":[]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[34]},{"op":"change_scene","args":[2,65535,65535,24,65535]},{"op":"actor_appear","args":[0,64,55,0,0]},{"op":"actor_appear","args":[24,64,47,2,0]},{"op":"actor_appear","args":[7,69,47,2,0]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":8},{"op":"actor_appear","args":[2,69,55,0,0]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":11},{"op":"actor_appear","args":[1,69,55,0,0]},{"op":"endif","args":[]},{"op":"fade_out","args":[]},{"op":"title_text","args":["重逢"]},{"op":"place_name","args":["蜀汉军军营外"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n仲权，想不到你还真的活着，实在是\n太好了。\n&姜维\n这段日子，包括皇后在内的人都在怀念\n你，现在可以让他们丢掉悲伤的心情了。"]},{"op":"actor_action","args":[7,6]},{"op":"dialog","args":["&夏侯霸\n父亲留给我的铠甲让我没有受到致命伤，\n经过皇甫大夫的救治，我侥幸保住一命。\n&夏侯霸\n之后辗转回到大魏，靠着七弟和女婿的\n帮助，一直在洛阳潜伏着。\n&姜维\n原来如此，能碰到皇甫大夫的救治，或许\n真是天命要仲权你继续活在人世。"]},{"op":"actor_action","args":[0,0]},{"op":"actor_action","args":[7,0]},{"op":"actor_action","args":[24,13]},{"op":"dialog","args":["&曹绫\n姜维，好久不见。"]},{"op":"actor_action","args":[24,0]},{"op":"dialog","args":["&姜维\n没想到真的是你。\n&曹绫\n距离上次相见应该已经三十多年，本来\n以为此生不可能再相见，没想到还能和你\n在这里重逢。\n&姜维\n我也没想到…真的很意外…"]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":33},{"op":"dialog","args":["&曹绫\n好久不见，自从上次洛阳一见之后，\n也过了差不多快十年了。\n&杨兰\n你来做什么？\n&曹绫\n好强的敌意。别担心，我只是来谈公事。\n&杨兰\n你以为我会相信你的鬼话？要谈事情\n只需要夏侯霸一个人来就够了。"]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&姜维\n杨兰，人家公主也是贵客…\n&杨兰\n闭嘴，现在是交战时期，容不得一点\n大意。"]},{"op":"actor_face","args":[7,0,3]},{"op":"dialog","args":["&夏侯霸\n公主，这怎么回事？\n&曹绫\n安静，这女人看来也不是头脑简单之辈。\n&夏侯霸\n（妈呀，真是六国大封相。）\n&曹绫\n这样下去真是没完没了，我们先说别的\n吧，等之后再一口气解决如何？\n&杨兰\n同意。"]},{"op":"actor_face","args":[0,0,0]},{"op":"actor_face","args":[7,0,2]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":45},{"op":"dialog","args":["&曹绫\n好久不见，自从上次寿春一见之后，\n也过了差不多快八年了。\n&诸葛果\n………\n&曹绫\n好强的敌意。别担心，我只是来谈公事。"]},{"op":"actor_face","args":[1,0,3]},{"op":"dialog","args":["&诸葛果\n主公，您相信曹操的孙女吗？"]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&姜维\n为什么不相信呢？\n&诸葛果\n既然这样，果也无话可说。\n&姜维\n（怎么连诸葛果都会这么表露出明显的\n怒气？）"]},{"op":"actor_face","args":[7,0,3]},{"op":"dialog","args":["&夏侯霸\n公主，这怎么回事？\n&曹绫\n安静，这女人看来也不是无欲之辈。\n&夏侯霸\n（妈呀，真是六国大封相。）\n&曹绫\n这样下去真是没完没了，我们先说别的\n吧，等之后再一口气解决如何？"]},{"op":"actor_face","args":[0,0,0]},{"op":"actor_face","args":[1,0,0]},{"op":"actor_face","args":[7,0,2]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[922],[]],"end":51},{"op":"dialog","args":["&曹绫\n真冷淡呀，想不到当初那么热心救我一命\n，等救到就觉得新鲜感没了？"]},{"op":"actor_face","args":[7,0,3]},{"op":"dialog","args":["&夏侯霸\n公主，这怎么回事？\n&曹绫\n高贵乡公遇害之时，我感觉曹家兴复无望\n，在邺城有了轻生的念头。\n&曹绫\n是姜维那封希望我不要放弃的信，让我\n获得重生的希望。\n&姜维\n不，那只是报你当年放过我的恩情而已。\n&曹绫\n这样下去真是没完没了，我们先别说\n这个吧。\n&曹绫\n（不过…真的很感谢你…要不然大魏今天\n岂有重生的希望。）"]},{"op":"actor_face","args":[7,0,2]},{"op":"endif","args":[]},{"op":"delay","args":[5]},{"op":"actor_action","args":[24,13]},{"op":"dialog","args":["&曹绫\n关于司马家篡位的事情，你应该有所\n耳闻吧。\n&姜维\n是的。不过因为对我们来说，不管是魏或\n是晋，敌人都不会改变，所以不会特别去\n在意。\n&曹绫\n那么我再告诉你，我们大魏已经在邺城\n起兵讨伐司马家。\n&姜维\n果然如此，司马昭一死，司马家的力量就\n衰弱许多，就算有后继人，恐怕也无法像\n过去一样能够完全统御部下。"]},{"op":"actor_action","args":[24,0]},{"op":"dialog","args":["&曹绫\n司马家篡夺大魏，天理不容，许多忠魏的\n志士也都起来反抗，包括镇北将军何曾、\n邺城督山涛，还有颖川陈家的陈泰。\n&姜维\n陈泰？！他不是已经病逝？\n&曹绫\n那是掩人耳目的手法，否则高贵乡公事件\n后，他如何能逃过司马昭的逼迫？\n&曹绫\n这次的起兵，规模可不小于淮南起义。\n我们拥兵超过十万，响应州郡无数，不日\n之间就可席卷黄河以北。\n&姜维\n等一下…既然你说起兵，为什么像你这样\n重要的人物会出现在这里？\n&夏侯霸\n伯约，因为我和公主认为，眼前的事情比\n那边的战场更重要。\n&夏侯霸\n那边可以交给陈泰，但是和你们的沟通却\n不能委由他们来做。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n单刀直入来说，就是想和你们结盟。\n&曹绫\n我们有着司马家这样共同的敌人，而敌人\n的势力强大，非我们联手不能对付。\n&曹绫\n一边在北，一边在西，甚至和东吴合作从\n东面进攻，才有机会打倒司马家。\n&姜维\n司马家的实力真的这么强大？\n&曹绫\n扣除我们大魏的幽、冀两州，以及目前\n属于你们的凉州以及所属未明的并州。\n&曹绫\n司马家仍然掌握了兖、豫、青、徐、荆、\n雍、扬和司等八州。\n&曹绫\n这八州加起来的兵力仍有超过四十万的\n可能，而且战力最强大的中军仍然握在\n司马家的手上。\n&曹绫\n过去司马家靠着中军夺权，对于中军战力\n的注重可以想见。现在我们光是面对都督\n军就已经苦战，面对中军时该怎么办？"]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":61},{"op":"dialog","args":["&姜维\n嗯…你怎么看呢？\n&杨兰\n单纯以战力考量来说，我认为这位公主\n说的没错。联手分散彼此的压力，确实\n是最正确的提案。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":64},{"op":"dialog","args":["&姜维\n嗯…你怎么看呢？\n&诸葛果\n请主公不要考虑到父亲的立场，他所处的\n时代不同，政治情况也不同。\n&诸葛果\n主公只要考虑这样的结盟，是否对大汉、\n甚至是主公有帮助就好。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&姜维\n能告诉我们，和你们结盟的条件？\n&曹绫\n不愧是蜀地的大将军，马上就切中要点。\n&曹绫\n为了表示诚意，皇上已经表示，他愿意\n削去皇帝称号。而且也愿意把洛阳双手\n奉还给你们。\n&姜维\n（皇帝？喔…应该是指曹芳吧。）\n&曹绫\n但是相对而言，你们必须承认我们大魏\n政权的存在，并且让我们继续立足在幽\n、冀两州。\n&夏侯霸\n我知道你们不承认我们政权的立场，但\n更不希望两国在击灭司马家后，还要刀兵\n相向。\n&姜维\n这种事情可不是我可以决定的…\n&曹绫\n很抱歉，我认可的谈判对手只有你，不是\n你们那个皇帝。\n&曹绫\n将在外，君命有所不受。\n&曹绫\n你应该可以马上做出该有的决定来。记住\n，战况随时在变化。万一我们茁壮，或是\n你们弱小了，这样的条件可不再有。"]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":68},{"op":"dialog","args":["&杨兰\n我是不懂你们汉人复杂的恩怨，若是说到\n曹家篡夺，现在曹家都愿意把皇位削去了\n，还有什么不能联合的？"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":71},{"op":"dialog","args":["&诸葛果\n主公，请先不要考虑陛下的事情。您不应\n该只是他一个人的臣子，而是整个大汉的\n臣子。\n&诸葛果\n请您站在您自己的立场，做出决定吧。"]},{"op":"endif","args":[]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n明日我会上书陛下，请他批准这样的\n同盟。\n&曹绫\n…这就是你的答案？\n&姜维\n不过，就算陛下反对这样的提案，我还是\n会贯彻同盟的约定。在攻下洛阳后，绝对\n不和你们刀剑相向。\n&夏侯霸\n伯约，谢谢你。"]},{"op":"actor_action","args":[24,3]},{"op":"dialog","args":["&曹绫\n你比我想像得有担当多了…拿着，这是\n表明双方盟约的信物。"]},{"op":"get_item","args":[39,0,0,0]},{"op":"actor_action","args":[24,0]},{"op":"delay","args":[5]},{"op":"if","cond":"comment","args":["曹綾S形象设定"],"end":81},{"op":"endif","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n盟约成立我是很欣慰，不过你不害怕以后\n会面临到周勃父子的命运？\n&姜维\n我并不怕，因为这是我的决定。\n&姜维\n（只要能够完成北伐大业，我个人的牺牲\n又算得了什么。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["刘禅的真意"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"dialog","args":["&刘禅\n姜维这个上书倒是有趣，居然请求朕答应\n和曹贼联手的事情。\n&黄皓\n陛下，姜维一而再，再而三做出越权叛逆\n的行为，实在不能再姑息他了。\n&刘禅\n黄皓呀，朕一直以为你懂朕的心。\n&刘禅\n如果朕可以成为光武帝甚至高祖，为什么\n要当刘璋呢？\n&刘禅\n还是你以为朕会像刘璋那样，杀掉赵韪，\n毁掉自己的屏障？\n&黄皓\n陛下，您真是把奴才搞胡涂了。\n&刘禅\n什么事情，都等到光复洛阳再说。在这\n之前，大将军说什么，朕都会答应的。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[645,34,54,1,0]},{"op":"actor_appear","args":[105,48,54,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["舐犊之爱"]},{"op":"place_name","args":["祁山 晋军营帐"]},{"op":"dialog","args":["&邓艾1\n忠儿？！你还活着？是我眼花了吗？"]},{"op":"actor_select","args":[0,105,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_appear","args":[128,48,54,3,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&文鸯\n你确实是眼花了，我是文鸯，记得过去\n还在乐嘉战场相见过。\n&邓艾1\n真像呀…那种没有谋略，只知往前冲杀的\n武人气息。\n&文鸯\n才短短几年没见，我所认识的邓艾就变成\n这样的失意老人？\n&邓艾1\n你说得对，刚才那些话就当作没听过吧。\n&邓艾1\n（忠儿，如果我当年尊重你的意愿，\n你会不会过得比较幸福呢？）"]},{"op":"actor_action","args":[128,6]},{"op":"dialog","args":["&文鸯\n我是奉圣上的命令，率领五百武卫营前来\n支援。\n&邓艾1\n五百？圣上知道情况的严重性？蜀人军队\n有六万，我们祁山这边的部队再怎么凑也\n只有两万。\n&文鸯\n莫非你不会打以寡击众的战争？"]},{"op":"actor_action","args":[128,0]},{"op":"actor_action","args":[645,2]},{"op":"dialog","args":["&邓艾1\n以优势兵力取得胜利是用兵的正道！\n&邓艾1\n现在大晋明明就还有数十万的军队，\n为什么不肯提拨部分部队来支援？\n&文鸯\n不过朝廷已经下旨要关中部队过来增援\n不是吗？"]},{"op":"actor_action","args":[645,0]},{"op":"dialog","args":["&邓艾1\n如果说关中部队是交给我指挥，要击破\n姜维绝对不是问题。\n&邓艾1\n但现在不是，关中都督司马亮要亲自带\n部队前来，你该知道问题了。\n&文鸯\n那家伙不可能会让你指挥他的，因为他是\n亲王，你地位在他之下。\n&邓艾1\n就是这样。\n&邓艾1\n陛下不知道问题的严重性，他比起他父亲\n或是伯父差太多了。\n&文鸯\n不用担心，就算只有现成的兵力，我还是\n有信心可以打败姜维。别忘记我过去怎么\n对付小师师的。\n&邓艾1\n你不要以为打仗都像是武将单挑，上次是\n你偶然，你不可能每次都这么幸运。\n&文鸯\n你终究是不明白我的实力呀，明明你和我\n交过手，却还是不肯相信自己的感受？\n&文鸯\n如果你的儿子像我一样是个武人，我想\n他一定会很痛苦的。\n&邓艾1\n（你懂什么？现在真正痛苦的是谁？\n我还是有老牛舐犊之爱呀。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[40]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[645,34,54,1,0]},{"op":"actor_appear","args":[149,48,43,2,0]},{"op":"actor_appear","args":[150,53,43,2,0]},{"op":"actor_appear","args":[151,58,43,2,0]},{"op":"actor_appear","args":[148,63,43,2,0]},{"op":"actor_appear","args":[129,68,43,2,0]},{"op":"actor_appear","args":[106,48,69,0,0]},{"op":"actor_appear","args":[718,53,69,0,0]},{"op":"actor_appear","args":[54,58,69,0,0]},{"op":"actor_appear","args":[128,63,69,0,0]},{"op":"actor_appear","args":[663,48,54,3,0]},{"op":"actor_appear","args":[118,53,51,3,0]},{"op":"actor_appear","args":[228,53,57,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["无能的亲王"]},{"op":"place_name","args":["祁山 晋军营帐"]},{"op":"dialog","args":["&王瓘\n邓艾！你好大胆子，明知道扶风王亲自\n率兵支援，你却不出来迎接。"]},{"op":"actor_action","args":[645,6]},{"op":"dialog","args":["&邓艾1\n我忙着规划作战策略，如果说有所得罪\n，也请多包涵。\n&司马亮\n不不不，本王一点也不在意，毕竟现在\n国难当头，正是应该要齐心合力来渡过\n这样的危机。\n&王韬\n（你不介意？不介意会刻意冷落降将组，\n把句安和蒋舒丢去守水塘？算了，至少\n他们不用再面对危险。）"]},{"op":"actor_action","args":[663,0]},{"op":"dialog","args":["&司马亮\n这次我率领关中部队超过八万人增援，\n配合你旗下的三万人，我们应该有敌人\n两倍的兵力。"]},{"op":"actor_action","args":[645,0]},{"op":"dialog","args":["&邓艾1\n兵力要说多少，对敌人可以随便说。但是\n请您不要在军事会议上还说假话。\n&邓艾1\n上次钟会和文皇帝征蜀败掉的部队，\n哪可能这么快补回来？\n&司马亮\n说来惭愧，其实我只有带来六万军队\n而已。\n&邓艾1\n有多少部队，我一看就知道，再玩文字\n游戏是没有用的。\n&司马亮\n其实只有四万人而已。\n&邓艾1\n四万…也就是说合起来应该可以到达六万\n人。\n&邓艾1\n蜀军号称六万，我想实际上能到祁山作战\n的，大概也只有四万，这样我们兵力应该\n是占优势。"]},{"op":"actor_action","args":[663,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&邓艾1\n我希望扶风王能以国事为重，将指挥权\n交给我。\n&司马亮\n这个…\n&王瓘\n开什么玩笑，凭什么亲王要听你一个外姓\n老将的指挥？\n&王颀\n好了不起的亲王呀，不知道是谁征讨\n诸葛诞的时候打得一蹋糊涂？"]},{"op":"actor_action","args":[106,0]},{"op":"dialog","args":["&师纂\n王颀！你竟敢对亲王说这种话，不怕脑袋\n搬家？\n&胡渊\n（简直就是一群胡闹的废物，这样下去，\n我真的能够为父报仇？）"]},{"op":"actor_action","args":[106,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[663,0]},{"op":"dialog","args":["&司马亮\n一切谨凭征西将军指挥。\n&邓艾1\n嗯，你能明白是再好不过了。\n&王瓘\n你这是什么态度！\n&司马亮\n我们走吧，请征西将军在完成布署后，再\n和我们联络。"]},{"op":"actor_move","args":[0,663,0,96,57,1]},{"op":"actor_move","args":[0,118,0,96,57,1]},{"op":"actor_move","args":[0,228,0,96,57,1]},{"op":"actor_select","args":[0,663,0,0,0,0,6]},{"op":"actor_select","args":[0,228,0,0,0,0,6]},{"op":"actor_select","args":[0,118,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&师纂\n我去送扶风王！\n&师纂\n（这个邓艾居然想要独揽指挥权，分明\n就是居心叵测，八成是要阵前投敌。）"]},{"op":"actor_move","args":[0,106,0,48,57,0]},{"op":"delay","args":[0]},{"op":"actor_move","args":[0,106,0,96,57,1]},{"op":"actor_select","args":[0,106,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[149,0,3]},{"op":"dialog","args":["&王颀\n征西将军，这样好吗？我总觉得这扶风王\n并没有要听从指挥的意思。\n&邓艾1\n钟会可以把诸葛绪绑到囚车，并吞他的\n军队，但我却不行。因为他是姓司马，\n我动他就是叛逆。\n&丘本\n真是没有道理，一改朝换代，那种货色就\n可以耀武扬威起来，明明就没有任何本事\n可言。\n&丘本\n打仗不行，在家盖农舍盖得富丽堂皇就\n很行，这些皇亲国戚真是败类。\n&邓艾1\n放他去吧，像他那种的人，能够做什么？\n他会做出来的事情我大概也掌握到了。\n&王颀\n请征西将军多加小心，诸葛诞殷鉴不远，\n我怕他来支援的目的并不单纯。"]},{"op":"actor_face","args":[128,0,3]},{"op":"dialog","args":["&文鸯\n我看你摆出来的阵型是鹤翼，只是这样\n的鹤翼真的安全吗？\n&文鸯\n两侧摆那些离心离德的关中部队，万一\n他们没有发挥包夹的效果，只怕中央本阵\n会被突破。\n&邓艾1\n确实，鹤翼阵的风险就是和两侧的联系\n会变得很困难。\n&邓艾1\n不过如果侧翼是这些不想听指挥的关中\n部队，就另当别论了。我要把他们逼上\n战场。\n&邓艾1\n文鸯，鹤翼阵的弱点在于中间防卫，\n你能够填补那样的缺口？\n&文鸯\n你当我是谁？我可是万人敌文俶。\n&邓艾1\n（忠儿，如果你还在世的话，本来这应该\n是你的任务。）\n&邓艾1\n（就算我尽了全力安排，现在陇西部队的\n素质还是令人担忧。）\n&邓艾1\n（部队新兵太多，不能用当年训练败残兵\n的方法训练他们。若是面对蜀人训练有素\n的部队，不知道能否抗衡。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[2,65535,65535,63,65535]},{"op":"actor_appear","args":[106,51,57,1,0]},{"op":"actor_appear","args":[663,57,57,3,0]},{"op":"actor_appear","args":[118,61,61,3,0]},{"op":"actor_appear","args":[228,61,54,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["密谋"]},{"op":"place_name","args":["祁山 晋军营帐"]},{"op":"dialog","args":["&司马亮\n这不是师主簿吗？"]},{"op":"actor_action","args":[106,6]},{"op":"dialog","args":["&师纂\n扶风王还能记得小人，小人感到异常\n荣幸。\n&司马亮\n不过你还真是失职呀，本来二哥派你去\n邓艾身边的目的，就是要你监视他，结\n果他居然张狂成这样。\n&师纂\n小人正是要和您商量此事。\n&司马亮\n若不是皇上下命，我才不想和那个打败仗\n的失意老将混在一起。\n&师纂\n这些事情，小人也同意扶风王的意见。\n&司马亮\n其实你知道我率军支援的真正目的？\n&师纂\n什么？！\n&司马亮\n陛下给了我一道密令，要我让姜维和邓艾\n打得两败俱伤，再趁机收回邓艾的兵权。\n&司马亮\n陛下的想法就和本王一样，只有姓司马\n的人才可以掌兵权。\n&司马亮\n（你们这些家伙也比邓艾都好不到哪去，\n全是些寒门单家出来的废物。）\n&司马亮\n（在大晋，只有出身高门的人才配称得上\n是人！）"]},{"op":"actor_action","args":[106,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&王瓘\n扶风王，小人倒是有个不错的提案。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[663,0,1]},{"op":"dialog","args":["&司马亮\n你说吧。\n&王瓘\n小人可以自称是王经的侄子，然后向蜀人\n诈降。\n&王瓘\n到时小人可以作引导，把姜维的大军带往\n邓艾的本阵。\n&王韬\n是说要让姜维突袭邓艾本阵？\n&王瓘\n完全正确。如此一来，我们两翼的关中\n部队不会受损，而只有陇西部队和姜维\n交战。\n&王瓘\n等两边厮杀得筋疲力竭时，我们再从两侧\n包夹歼灭。\n&王瓘\n到时您不但是胜利的大功臣，邓艾的\n部队也会伤得七七八八，要夺他的兵权\n还不容易吗？\n&司马亮\n妙计，就照你的方法去实行。\n&王韬\n（这家伙是白痴吗？每个人都知道王经\n是被屠灭三族的罪人，哪可能有侄子在\n外。）\n&王韬\n（姜维一定会识破这样的计谋，但问题是\n邓艾呢？要是邓艾他会怎么做呢？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[25]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":8},{"op":"if","cond":"comment","args":["杨兰头像设定"],"end":5},{"op":"endif","args":[]},{"op":"if","cond":"comment","args":["杨兰R形象设定"],"end":7},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":10},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[922],[]],"end":12},{"op":"endif","args":[]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[23,46,45,2,0]},{"op":"actor_appear","args":[17,51,45,2,0]},{"op":"actor_appear","args":[15,56,45,2,0]},{"op":"actor_appear","args":[4,61,45,2,0]},{"op":"actor_appear","args":[3,66,45,2,0]},{"op":"actor_appear","args":[2,71,45,2,0]},{"op":"actor_appear","args":[16,76,45,2,0]},{"op":"actor_appear","args":[24,46,66,0,0]},{"op":"actor_appear","args":[7,51,66,0,0]},{"op":"actor_appear","args":[9,56,66,0,0]},{"op":"actor_appear","args":[1,61,66,0,0]},{"op":"actor_appear","args":[21,66,66,0,0]},{"op":"actor_appear","args":[22,71,66,0,0]},{"op":"actor_appear","args":[20,76,66,0,0]},{"op":"actor_appear","args":[14,81,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["决战中的较量"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"dialog","args":["&句扶\n能够亲眼确定夏侯将军没死，实在是\n太好了。\n&夏侯霸\n不能铲除司马老贼的势力，我怎么能就\n这样去见太初和昭伯。"]},{"op":"actor_action","args":[7,6]},{"op":"dialog","args":["&夏侯霸\n现在我们大魏势力和你们联手，目标就是\n要打倒篡逆的司马家。"]},{"op":"actor_action","args":[7,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&张星彩\n这个人就是贼营…不，大魏的公主？\n真没想到我们也有和曹操后代联手的\n一天。\n&曹绫\n我也听夏侯将军提起过你，据说你是完全\n继承张飞将军的人。\n&关索\n公主，回想起来，你的祖父和我的父亲也\n是惺惺相惜，不如我们也来重拾曹关两家\n的交情吧。\n&张星彩\n请不要理会这个大汉的耻辱，关伯伯和\n这位耻辱先生没有什么关系。\n&关索\n别这样说！我老爹当年也喜欢美人呀。\n他人帅，留胡子又有礼貌，和我一样是\n万人迷呢。\n&曹绫\n（话说回来，关羽过去似乎也和祖父要过\n杜氏，或许真相是…）"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n这是攸关我们大汉命运的重要会战，也是\n自从段谷之战后，再一次和邓艾在此地\n交手，意义格外重大。\n&姜维\n但是现在的情况和当时大不相同，我军\n粮食充沛，没有断粮危机。军队人数也\n充足，不再需要面对以寡击众的状况。\n&姜维\n只要我们能越过邓艾这一关，相信绝对\n可以克复中原，还都洛阳！"]},{"op":"actor_action","args":[0,0]},{"op":"actor_face","args":[3,6,3]},{"op":"dialog","args":["&柳隐\n老大，关于那个自称王经侄子的人，你要\n怎么处置呀。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[7,6,3]},{"op":"dialog","args":["&夏侯霸\n伯约，王经的三族全被屠灭，根本就\n不可能有什么侄子存在。"]},{"op":"choice","args":["利用王瓘的投降\n接纳王瓘的投降",0]},{"op":"if","cond":"always","args":[],"end":55},{"op":"if","cond":"test_choice","args":[1],"end":51},{"op":"dialog","args":["&姜维\n我知道，这种一目了然的诈降非常愚蠢，\n只是如果考虑到邓艾呢？\n&夏侯霸\n邓艾不可能会采用这么愚蠢的计谋吧。\n&姜维\n确实不可能，不过如果考虑到邓艾利用\n这样的计谋再来设圈套呢？\n&夏侯霸\n原来如此。\n&姜维\n防范邓艾的圈套，然后再利用这个王瓘\n找出突破点。"]},{"op":"set_flag","args":[1040,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":54},{"op":"dialog","args":["&姜维\n话虽如此，我们就暂且假意接纳他，看他\n能玩出什么把戏。"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"actor_face","args":[17,6,3]},{"op":"dialog","args":["&廖化\n伯约，面对邓艾这个前所未见的强敌，\n可不能只用一个计策。\n&廖化\n在座的每个人或许都有自己的计策，可以\n斟酌考量。\n&姜维\n元俭……\n&廖化\n别误会了，我也想要报过去邓艾给我的\n屈辱，并不是说要支持你。\n&廖化\n你的举动我还是很不满，请你要记住\n这点。"]},{"op":"actor_face","args":[17,0,2]},{"op":"actor_face","args":[3,0,2]},{"op":"actor_face","args":[7,0,0]},{"op":"delay","args":[5]},{"op":"play_sound","args":[21]},{"op":"battle_select_units","args":[1,15,65535,24,2,1,0,65535,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,15,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,15,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"endif","args":[]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n出击！拿下祁山，就等于拿下陇西！"]},{"op":"battle_select_units","args":[0,0,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[255]},{"op":"endif","args":[]},{"op":"dialog","args":["&关索\n真是不公平，大将军有三个女人大家都不\n说话，我随便把个妹就被瞧不起。\n&姜维\n关将军，请别随便乱说。\n&张星彩\n你摸着良心说，你只是随便把个妹？\n&花鬘\n同时和四个女人订婚约的是哪个人\n的啦。\n&关索\n对不起，我错了。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&张嶷\n要破邓艾，就只能制造不利于他的势，\n正面对抗其实胜算很小。\n&张嶷\n伯约如果让我出击的话，因为过去邓艾\n曾经受挫于我两次，或多或少可以给他\n一点心理压力。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&杨兰\n都已经到这里了，就一口气冲破那讨人厌\n的邓艾。\n&杨兰\n只要邓艾破了，冀城就在眼前。"]},{"op":"if","cond":"test_flags","args":[[920],[]],"end":6},{"op":"dialog","args":["&姜维\n咦，杨兰你怎么好像换了一身打扮？"]},{"op":"dialog","args":["&杨兰\n少女当然要经常换不同的装束啦，这是\n常识、常识！"]},{"op":"dialog","args":["&马隆\n（阿姨您贵庚？）"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"dialog","args":["&姜维\n恭喜孟姑娘和关将军结为夫妇。\n&花鬘\n咦？你没听说吗？关索新婚当天逃跑。\n这到底算不算成亲还不知道呢。\n&杨兰\n真不敢相信。\n&张星彩\n天底下就有这么差劲的男人。\n&诸葛果\n关将军刻意想让婚礼仪式无效的想法是\n可以理解的。\n&曹绫\n我顿时觉得夏侯楙也是个好丈夫了。\n&关索\n呜…"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":3},{"op":"dialog","args":["&袁綝\n伯约，事到如今我还是要提醒你一句，\n多注意身边陪伴着你的人。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[921]],"end":6},{"op":"dialog","args":["&袁綝\n（这个叫曹绫的女人，似乎她母亲曾经是\n兄长的妻子，或许知道更多袁氏的事。）"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[624]],"end":9},{"op":"dialog","args":["&曹绫\n邓艾的部队并不是像过去那样是一个群体\n，他的内部有不安定因素。\n&曹绫\n在鹤翼阵两边侧翼都是司马亮的军队，\n由于司马亮地位高过邓艾，邓艾对他们\n并不能完全控制。\n&姜维\n司马亮是个什么样的人？\n&曹绫\n他是司马懿的四子，看起来很勇敢，\n其实是个没安全感的胆小鬼。\n&曹绫\n现在司马亮应该会担心邓艾从背后暗算他\n，所以我建议我们可以稍微进逼，只要让\n他感受到被歼灭的威胁，他会即刻撤兵。\n&曹绫\n仔细考虑一下吧，若是鹤翼阵两翼全断，\n破阵是轻而易举之事。"]},{"op":"if","cond":"test_choice","args":[1],"end":5},{"op":"set_flag","args":[625,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":7},{"op":"endif","args":[]},{"op":"set_flag","args":[624,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[624],[]],"end":12},{"op":"dialog","args":["&曹绫\n放心吧，邓艾也是人。不管他再怎么厉害\n，手头资源大量减少的他已非不能击败。"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[626]],"end":10},{"op":"dialog","args":["&诸葛果\n主公，邓艾旗下有个名叫师纂的人，\n不知道您听过吗？\n&诸葛果\n师纂是司马昭派去监视邓艾的人，只是\n后来司马昭战死，他也无法回去洛阳。\n&诸葛果\n主公，要一劳永逸解决邓艾，就得利用\n师纂。\n&诸葛果\n只是这样的计策并不正大光明，希望主公\n您定夺。"]},{"op":"if","cond":"test_choice","args":[1],"end":6},{"op":"dialog","args":["&诸葛果\n如果您同意的话，在战场上请让果接触\n到师纂。\n&姜维\n好，我明白了。"]},{"op":"set_flag","args":[623,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":8},{"op":"endif","args":[]},{"op":"set_flag","args":[626,1]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[626],[]],"end":17},{"op":"dialog","args":["&诸葛果\n主公，邓艾再怎么厉害，还是有无法战胜\n的对手。\n&诸葛果\n那就是人心…"]},{"op":"if","cond":"test_flags","args":[[921],[]],"end":16},{"op":"dialog","args":["&姜维\n为什么我感觉你好像也有些微妙地变了？"]},{"op":"dialog","args":["&诸葛果\n主公明察秋毫，果佩服万分。"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"dialog","args":["&张翼\n这场战争不只是关系大汉的未来，也关系\n到我们益州人的未来，我一定会全力战斗\n的。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&张星彩\n我听说文鸯这个人也到了祁山，虽然\n没亲眼看过他，但是听说是个不好惹\n的家伙。\n&张星彩\n我没有把握可以打败文鸯，不过万一他\n效法当日乐嘉之战时，往我们本营突进\n时，请让我来阻挡他。\n&张星彩\n当然，如果没有让我出击的话，只怕没人\n可以挡得住文鸯。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&夏侯霸\n久违的并肩作战。从现在起，我不会再有\n什么心理负担，大家都是为打倒司马家而\n战。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&马隆\n邓艾用的是鹤翼阵，此阵在包围歼灭方面\n是最强大的阵型。\n&马隆\n由此可知，邓艾这边的兵力在我们之上。\n&马隆\n话虽如此，只要击中攻击中央本阵，鹤翼\n仍是可以击破。只是…邓艾应该不会这么\n简单放松中央的防备。\n&马隆\n我有个提议，以八阵之法强化本营防御，\n到时就算面对邓艾的奇袭，也不至于会\n慌乱。\n&马隆\n若您同意的话，请一定要让我出击。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&廖化\n如果伯约相信我的话，请让我出击。\n&廖化\n我想以分队深入邓艾鹤翼阵的侧腹或是\n背后。\n&姜维\n（邓艾诡计多端，元俭如果不能临时应变\n，恐怕反而会中计，我是不是该在这时候\n信赖元俭的判断能力呢？）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&罗宪\n在下人一直在巴东，但是听闻多次关于\n邓艾的事迹，总想和他较量一番。\n&罗宪\n今天算是得尝宿愿吧。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&柳隐\n老大，不管你是否采用迁出外地人的政策\n，我都还是会支持你的。\n&柳隐\n只是…我反而会担心你因为这样的提案而\n被打压。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&宁随\n………\n&姜维\n你在想什么吗？\n&宁随\n没什么，伯约你多虑了。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&句扶\n总觉得不管我们怎么逃避，邓艾都会持续\n出现在我们面前。\n&姜维\n所以我们一定要越过邓艾这道障碍才行。"]},{"op":"endif","args":[]},{"op":"enter_battle","args":[]}]},"battles":[{"src":"S_39"}]});
})();
